INSERT INTO `group_questions` (`group_id`, `group_question_order`, `group_audio`, `group_image`, `group_text`, `group_transcript`, `test_id`, `part_id`, `question_type_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '32-34', '{\"asset_id\":\"df5d43e03746de50516831b8dff11fb3\",\"public_id\":\"toeic/2020/test1/question_audio/32-34\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186910/toeic/2020/test1/question_audio/32-34.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186910/toeic/2020/test1/question_audio/32-34.mp3\",\"duration\":39.314286}', NULL, NULL, '<p><strong>M-Au:</strong>&nbsp;Hi, Maria. (32) Were you able to starton the wedding cakes yet?</p><p><strong>W-Br:</strong>&nbsp;(32) Yes, I\'ve started onthe Anderson order. It\'s a little more complex than I thought itwould be.</p><p><strong>M-Au:</strong>&nbsp;Yes, they\'re morecomplicated and they do take a little more time, but it\'ll be worthit.</p><p><strong>W-Br:</strong>&nbsp;Right. (33) We candefinitely increase our bakery\'s sales by offering wedding cakes.Take a look—is the color of this frosting. OK?</p><p><strong>M-Au:</strong>&nbsp;Actually,the order called for a dark pink. This is a little too pale. (34) Letme get some more food coloring from the supply closet.</p><p><strong>M-Au:&nbsp;</strong>Xin chào, Maria.&nbsp;(32) Bạn đã có thể bắt đầu với những chiếc bánh cưới chưa?</p><p><strong>W-Br:</strong>&nbsp;(32) Có, tôi đã bắt đầu với đặt hàng của Anderson. Nó phức tạp hơn một chút so với tôi nghĩ.&nbsp;</p><p><strong>M-Au:&nbsp;</strong>Vâng, chúng phức tạp hơn và chúng mất nhiều thời gian hơn một chút, nhưng nó sẽ có giá trị.&nbsp;</p><p><strong>W-Br:&nbsp;</strong>Phải.&nbsp;(33) Chúng ta chắc chắn có thể tăng doanh số bán hàng của chúng ta bằng cách cung cấp bánh cưới.&nbsp;Hãy nhìn vào màu sắc của lớp phủ đường (frosting - lớp phủ bánh) này.&nbsp;Đồng ý chứ?</p><p><strong>M-Au:</strong>&nbsp;Thật ra, đặt hàng yêu cầu màu hồng đậm.&nbsp;Như thế này là hơi nhạt một chút.&nbsp;(34) Hãy để tôi lấy thêm một số màu thực phẩm từ tủ cung cấp.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(2, '35-37', '{\"asset_id\":\"bb5bc15c1ef3061d073c1b98c09fc956\",\"public_id\":\"toeic/2020/test1/question_audio/35-37\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/35-37.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/35-37.mp3\",\"duration\":38.739592}', NULL, NULL, '<p>M-Cn: Hi. Joanne. I didn\'t know you rode abike to work. When did you start doing that?</p><p><br></p><p>W-Am: Last week. The town just added anew bike lane on Felton Road, so now I can ride here.</p><p><br></p><p>M-Cn: That\'s great. I heard the towngovernment is planning to add bike lanes on some other roadstoo.</p><p><br></p><p>W-Am: It\'s really convenient.&nbsp;My commuteto work used to be an hour by bus, and now it\'s only 25minutes.</p><p><br></p><p>M-Cn: Wow. You know, I\'m a member of alocal bike-riding club that takes tours on the weekends. You shouldjoin. It\'s a great group.</p><p>M-Cn: Xin chào.&nbsp;Joanne.&nbsp;Tôi không biết bạn đã đạp xe đi làm.&nbsp;Bạn đã bắt đầu làm điều đó khi nào vậy?&nbsp;</p><p>W-Am: Tuần trước.&nbsp;(35) Thị trấn vừa thêm một làn đường xe đạp mới trên đường Felton, vì vậy bây giờ tôi có thể đạp xe ở đây.&nbsp;</p><p>M-Cn: Thật tuyệt vời.&nbsp;Tôi nghe nói chính quyền thị trấn đang lên kế hoạch thêm làn đường cho xe đạp trên một số con đường khác.&nbsp;</p><p>W-Am: Nó thực sự tiện lợi. (36) Việc đi lại của tôi trước đây là một giờ bằng xe buýt và giờ chỉ còn 25 phút.</p><p>M-Cn: Wow.&nbsp;Bạn biết đấy, tôi là thành viên của một câu lạc bộ đạp xe địa phương tham gia các tour vào cuối tuần.&nbsp;Bạn nên tham gia.&nbsp;Đó là một nhóm tuyệt vời.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(3, '38-40', '{\"asset_id\":\"fdbc451f1b507c14375bc1ec69f4db1d\",\"public_id\":\"toeic/2020/test1/question_audio/38-40\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/38-40.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/38-40.mp3\",\"duration\":44.199184}', NULL, NULL, '<p>M-Au: Hello, Ms. Wilson? This is OliverLewis calling from Kardack Engineering. I reviewed yourapplication for the mechanical engineer position and would like tointerview you.</p><p>W-Am: Oh, I\'m happy to hear that.</p><p>M-Au: Good. I\'ll transfer you to myadministrative assistant. He\'ll make the arrangements for theinterview.</p><p>W-Am: Great.</p><p>M-Cn: Hello, Ms. Wilson. This is Mr.Lewis\' assistant. Martin. I\'m wondering if Wednesday at nine A.M.works for you.</p><p>W-Arn: Yes, that\'s perfect. Now, I\'ve neverbeen to your office complex before. Where can I finddirections?</p><p>M—Cn:&nbsp;I\'ll e-mail those to you.</p><p>M-Au: Xin chào, cô Wilson? Đây là Oliver Lewis gọi từ Kardack Engineering. Tôi đã xem xét hồ sơ ứng tuyển của bạn cho vị trí kỹ sư cơ khí và muốn phỏng vấn bạn.</p><p>W-Am: Ồ, tôi rất vui khi nghe điều đó.</p><p>M-Au: Tốt. Tôi sẽ chuyển bạn cho trợ lý hành chính của tôi. Anh ấy sẽ sắp xếp cho cuộc phỏng vấn.</p><p>W-Am: Tuyệt vời.</p><p>M-Cn: Xin chào, cô Wilson. Đây là trợ lý của ông Lewis. Martin. Tôi đang tự hỏi nếu thứ tư lúc chín giờ sáng có tiện cho bạn không?</p><p>W-Arn: Vâng, điều đó thật hoàn hảo. Hiện tại, tôi chưa bao giờ đến khu phức hợp văn phòng của bạn trước đây. Tôi có thể tìm chỉ dẫn đường đi ở đâu?</p><p>M-Cn: Tôi sẽ gửi e-mail cho bạn.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(4, '41-43', '{\"asset_id\":\"4dfc4b3804137d673c1b52fd1bae77c0\",\"public_id\":\"toeic/2020/test1/question_audio/41-43\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186909/toeic/2020/test1/question_audio/41-43.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186909/toeic/2020/test1/question_audio/41-43.mp3\",\"duration\":45.061224}', NULL, NULL, '<p>M-Cn: Good morning, (41) you\'ve reachedTaylor Dental. How can I help you?</p><p>W-Br:&nbsp;Hi. This is Susan Walker,one of Dr. Taylor\'s patients. I\'d like to schedule an appointment fora teeth cleaning this Friday. Will that be possible?</p><p>M-Cn:&nbsp;Unfortunately, we\'re allbooked this week. But (42) if someone cancels and an appointmentopens up, I could contact you.</p><p>W-Br:&nbsp;Sure, thanks.</p><p>M-Cn: I should let you know, in case you doget an appointment, that “our parking area is under constructionthis week, so you can\'t park there.</p><p>W-Br:&nbsp;Oh no (43) I don\'tknow of any other parking areas nearby.</p><p>M-Cn: Well, the Number 10 bus stops rightoutside our building.</p><p>M-Cn: Chào buổi sáng, (41) bạn đã gọi đến Nha khoa Taylor.&nbsp;Tôi có thể giúp gì cho bạn?&nbsp;</p><p>W-Br: Xin chào.&nbsp;Đây là Susan Walker, một trong những bệnh nhân của bác sĩ Taylor.&nbsp;Tôi muốn sắp xếp một cuộc hẹn để làm sạch răng vào Thứ sáu này.&nbsp;Điều đó sẽ có thể chứ?&nbsp;</p><p>M-Cn: Thật không may, tất cả chúng tôi đã đặt trước trong tuần này.&nbsp;Nhưng (42) nếu ai đó hủy hẹn và một cuộc hẹn trống, tôi có thể liên lạc với bạn.&nbsp;</p><p>W-Br:Vâng, cảm ơn.&nbsp;</p><p>M-Cn: Tôi nên cho bạn biết, trong trường hợp bạn có một cuộc hẹn, rằng \"khu vực đỗ xe của chúng tôi đang được xây dựng trong tuần này, vì vậy bạn không thể đỗ xe ở đó.</p><p>W-Br: Ồ không (43) Tôi không biết bất kỳ chỗ đỗ xe nào gần đó.</p><p>M-Cn: Chà, xe buýt số 10 dừng ngay bên ngoài tòa nhà của chúng tôi.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(5, '44-46', '{\"asset_id\":\"ef465fcb248834275682585b9d436322\",\"public_id\":\"toeic/2020/test1/question_audio/44-46\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/44-46.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/44-46.mp3\",\"duration\":31.425306}', NULL, NULL, '<p>M-Cn: Hi. (44) Welcome to ChestertonBank. How can I help you?</p><p>W-Br:&nbsp;Well, (45) I\'d like to depositmy paycheck into my savings account.</p><p>M-Cn:&nbsp;Of course. Have you thoughtabout signing up for direct deposit? That way, your paycheck will godirectly into your account, and you don\'t have to come in to thebranch to do the transaction.</p><p>W- Br:&nbsp;That sounds great,actually.</p><p>M-Cn:&nbsp;(46) You just need to fillout some paperwork. I\'ll go prepare that now so you can sign uptoday.</p><p>M-Cn: Xin chào.&nbsp;(44) Chào mừng đến với ngân hàng Chesterton.&nbsp;Tôi có thể giúp gì cho bạn?&nbsp;</p><p>W-Br: Chà, (45) Tôi muốn gửi tiền lương vào tài khoản tiết kiệm của mình.&nbsp;</p><p>M-Cn: Tất nhiên rồi.&nbsp;Bạn đã nghĩ về việc đăng ký gửi tiền trực tiếp?&nbsp;Bằng cách đó, tiền lương của bạn sẽ đi thẳng vào tài khoản của bạn và bạn không phải đến chi nhánh để thực hiện giao dịch.&nbsp;</p><p>W- Br: Thật ra, thế thì tuyệt quá.&nbsp;</p><p>M-Cn: (46) Bạn chỉ cần điền vào một số giấy tờ.&nbsp;Tôi sẽ đi chuẩn bị ngay bây giờ để bạn có thể đăng ký ngay hôm nay.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(6, '47-49', '{\"asset_id\":\"c0f40ebd971050722058cddf3b85041e\",\"public_id\":\"toeic/2020/test1/question_audio/47-49\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/47-49.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/47-49.mp3\",\"duration\":35.73551}', NULL, NULL, '<p>W-Br:&nbsp;Good morning, Hakim. “Theprototype for our new refrigerator is ready to show to our appliancedistributors from Malaysia today.</p><p>M-Au:&nbsp;Oh, it turns out we had toreschedule the meeting about the refrigerator. (48) Their flight wasdelayed, and their plane won\'t be arriving until this evening.</p><p>W-Br:&nbsp;So I guess they\'ll be goingstraight to their hotel, then. (49) Should I arrange for a car serviceto pick them up in the morning?</p><p>M-Au: (49) Yes, thanks. Around nine o\'clockwould be good.</p><p>W-Br: OK. I\'ll do that right now.</p><p>W-Br: Chào buổi sáng, Hakim.&nbsp;\"Nguyên mẫu cho tủ lạnh mới của chúng ta đã sẵn sàng để trình bày cho các nhà phân phối thiết bị của chúng ta từ Malaysia hôm nay.</p><p>M-Au: Ồ, hóa ra chúng ta đã phải dời lại lịch cuộc họp về tủ lạnh. (48) Chuyến bay của họ bị hoãn và máy bay của họ sẽ không thể đến cho đến tối nay.</p><p>W-Br: Vì vậy, tôi đoán sau đó họ sẽ đi thẳng đến khách sạn của họ. (49) Tôi có nên sắp xếp xe để đón họ vào buổi sáng không?</p><p>M-Au: (49) Có, cảm ơn. Khoảng chín giờ thì tốt.</p><p>W-Br: OK. Tôi sẽ làm điều đó ngay bây giờ.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(7, '50-52', '{\"asset_id\":\"5ec60172ee891400d176b6c62efbb34c\",\"public_id\":\"toeic/2020/test1/question_audio/50-52\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/50-52.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/50-52.mp3\",\"duration\":34.66449}', NULL, NULL, '<p>W-Am: Hello, (50) welcome to the ChemistryResearch Conference. Here\'s your name badge and welcome packet. Itincludes a program with a schedule of conference events.</p><p>M-Cn: Thank you! Do you happen to know ifthere\'ll be a question—and-answer session after each presentation?(51) I have a question for one of the speakers.</p><p>W-Am: Yes, there\'ll be a few minutes at theend of each session for that. Oh and before you go in, (52) don\'tforget to choose a travel mug from the next tab|e—we have twodifferent colors this year.</p><p>W-Am: Xin chào, (50) chào mừng đến với Hội nghị Nghiên cứu Hóa học. Đây là huy hiệu tên của bạn và bộ tài liệu.&nbsp;Nó bao gồm một kế hoạch với lịch trình các sự kiện hội nghị.&nbsp;</p><p>M-Cn: Cảm ơn bạn!&nbsp;Bạn có tình cờ biết liệu sẽ có một câu hỏi và phiên trả lời sau mỗi phần trình bày không?&nbsp;(51) Tôi có một câu hỏi cho một trong những diễn giả.&nbsp;</p><p>W-Am: Vâng, sẽ có một vài phút vào cuối mỗi phiên cho việc đó.&nbsp;Ồ và trước khi bạn đi vào, (52) đừng quên chọn một chiếc cốc du lịch ở bàn tiếp theo. Chúng tôi có hai màu khác nhau trong năm nay.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(8, '53-55', '{\"asset_id\":\"d4a56d0dff52e8a6cef8a8308f0af414\",\"public_id\":\"toeic/2020/test1/question_audio/53-55\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/53-55.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/53-55.mp3\",\"duration\":37.381224}', NULL, NULL, '<p>M-Au: Hi, (53) this is Takumi from ColorPrinting Solutions. (54) I e-mailed you the mock-up of</p><p>yourcompany\'s flyer this morning. Have you had time to review it?</p><p>W-Am: Oh hi, Taku mi. (54) I just saw yourdraft of the flyer and was about to call you myself. We actually havea new company logo.</p><p>M-Au: OK, no problem. Can you send it to mebefore lunch? That way I can be sure to finish the print job by theend of today as promised.</p><p>W-Am: Sure! (55) Please charge the order tothe credit card you have on file for our account.</p><p>M-Au: Xin chào, (53) đây là Takumi từ Giải pháp in màu.&nbsp;(54) Tôi đã gửi mail cho bạn bản nháp tờ rơi của công ty bạn sáng nay.&nbsp;Bạn đã có thời gian để xem xét nó chưa?&nbsp;</p><p>W-Am: Oh hi, Taku mi.&nbsp;(54) Tôi vừa xem bản nháp của bạn và đang định gọi bạn.&nbsp;Chúng tôi thực ra có một logo mới của công ty.&nbsp;</p><p>M-Au: OK, không vấn đề gì.&nbsp;Bạn có thể gửi nó cho tôi trước khi ăn trưa chứ?&nbsp;Bằng cách đó tôi có thể chắc chắn hoàn thành công việc in vào cuối ngày hôm nay như đã hứa.&nbsp;</p><p>W-Am: Chắc chắn rồi!&nbsp;(55) Vui lòng tính phí đơn hàng vào thẻ tín dụng bạn có trong hồ sơ cho tài khoản của chúng tôi.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(9, '56-58', '{\"asset_id\":\"9427287380e95825ade22a08deaf4f8d\",\"public_id\":\"toeic/2020/test1/question_audio/56-58\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/56-58.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/56-58.mp3\",\"duration\":42.997551}', NULL, NULL, '<p>W-Br: A lot more people have been visitingthe museum lately-(56) my tours have been completely full! What aboutyours, Emily?</p><p>W-Am: (56) Mine, too. (57) I think it\'sbecause of the new art exhibit-the one that was donated by JunoSiska. It would be interesting to know how she started collectingart.</p><p>M-Au: Well, I just heard that (58) Ms. Siskawill be here next Thursday afternoon to talk about her collection.I\'m sure there\'ll be a chance to ask her questions.</p><p>W-Am: That sounds great. How much are ticketsto that event?</p><p>M-Au: Oh, you won\'t have to pay. Everyone whoworks at the museum gets in free of charge.</p><p>W-Br: Gần đây có rất nhiều người đã đến thăm bảo tàng (56) các tour du lịch của tôi đã hoàn toàn kín!&nbsp;Còn bạn thì sao Emily?&nbsp;</p><p>W-Am: (56) Của tôi cũng vậy.&nbsp;(57) Tôi nghĩ rằng đó là vì triển lãm nghệ thuật mới - tác phẩm được tặng bởi Juno Siska. Thật thú vị khi biết cô ấy bắt đầu sưu tập nghệ thuật như thế nào.&nbsp;</p><p>M-Au: Chà, tôi vừa nghe rằng (58) Cô Siska sẽ ở đây vào chiều thứ năm tới để nói về bộ sưu tập của cô ấy.&nbsp;Tôi chắc chắn sẽ có cơ hội để hỏi cô ấy câu hỏi.&nbsp;</p><p>W-Am: Nghe thật tuyệt. Bao nhiêu tiền cho vé của sự kiện đó?&nbsp;</p><p>M-Au: Ồ, bạn sẽ không phải trả tiền. Mọi người làm việc tại bảo tàng đều được miễn phí.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(10, '59-61', '{\"asset_id\":\"924def0c1b8a0a21559547ec26e2220e\",\"public_id\":\"toeic/2020/test1/question_audio/59-61\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/59-61.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/59-61.mp3\",\"duration\":41.874286}', NULL, NULL, '<p>M-Cn: Hi, (59) I bought this computer justthe other day, but I think it may be defective. The operating systemsoftware has frozen on me several times already.</p><p>W-Br: Well - freezes are common during setup,and there\'s an easy fix for that. We do offer technical support for asmall fee, if you’re interested.</p><p>M-Cn: Isn\'t that included in my insurancepackage?</p><p>W-Br: Oh -(60) you bought our insurance! Yes,(60) technical support is one of the benefits. (61) What’s yourphone number, please? I can pull up your policy with thatnumber.</p><p>M-Cn: It\'s 555-0144.</p><p>M-Cn: Xin chào, (59) Tôi mới mua máy tính này bữa trước, nhưng tôi nghĩ nó có thể bị lỗi. Phần mềm hệ điều hành đã đóng băng trên tôi nhiều lần rồi.</p><p>W-Br: Vâng - đóng băng là phổ biến trong khi thiết lập, và có một sửa chữa dễ dàng cho điều đó. Chúng tôi cung cấp hỗ trợ kỹ thuật cho một khoản phí nhỏ, nếu bạn quan tâm.</p><p>M-Cn: Không có trong gói bảo hiểm của tôi phải không?</p><p>W-Br: Oh - (60) bạn đã mua bảo hiểm của chúng tôi! Có, (60) hỗ trợ kỹ thuật là một trong những lợi ích. (61) Xin vui lòng cho số điện thoại của bạn. Tôi có thể xem chính sách của bạn với số đó.</p><p>M-Cn: Đó là 555-0144.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(11, '62-64', '{\"asset_id\":\"cfe610fc44ab990be43cf7b45204e446\",\"public_id\":\"toeic/2020/test1/question_audio/62-64\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/62-64.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/62-64.mp3\",\"duration\":39.235918}', '{\"asset_id\":\"e3de6ace3cd5681f009668c7d682e466\",\"public_id\":\"toeic/2020/test1/question_image/62-64\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/62-64.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/62-64.webp\"}', NULL, '<p>W-Am: Hey, David. (62) Our clients are comingfrom overseas next week, and we need to order the food for thewelcome dinner. Which of these dishes do you think we shouldget?</p><p>M-Au: Well, the last time we had clientshere, we ordered the vegetable pasta. Everyone really liked it.</p><p>W-Am: Yeah, I remember. But this time we havea larger budget, so I wanted to order something different.</p><p>M--Au: (63) Why don\'t we order the bakedsalmon?</p><p>W-Am: I was thinking that, too. Also, (64) westill have to call and confirm the hotel booking for our clients. I\'mgoing to do that now.</p><p>Menu Options</p><p>Stuffed Eggplant $6 per person</p><p>Vegetable Pasta $8 per person</p><p>Roast Chicken $10 per person</p><p>(63) Bakod Salmon $12 per person</p><p><br></p><p>W-Am: Này, David. (62) Khách hàng của chúng ta sẽ đến từ nước ngoài vào tuần tới, và chúng ta cần đặt món ăn cho bữa tối chào mừng. Những món ăn nào bạn nghĩ rằng chúng ta nên đặt?</p><p>M-Au: Chà, lần cuối cùng chúng ta có khách hàng ở đây, chúng ta đã gọi món mì ống rau. Mọi người đều thực sự thích nó.</p><p>W-Am: Vâng, tôi nhớ. Nhưng lần này chúng ta có ngân sách lớn hơn, vì vậy tôi muốn đặt một vài món khác biệt.</p><p>M - Au: (63) Tại sao chúng ta không gọi món cá hồi nướng?</p><p>W-Am: Tôi cũng đã nghĩ vậy. Ngoài ra, (64) chúng ta vẫn phải gọi và xác nhận đặt phòng khách sạn cho khách hàng của chúng ta. Tôi sẽ làm điều đó bây giờ.</p><p>Tùy chọn menu</p><p>Cà tím nhồi $6 mỗi người</p><p>Pasta rau củ $8 mỗi người</p><p>Gà nướng $10 mỗi người</p><p>(63) Cá hồi nướng $12 mỗi người</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(12, '65-67', '{\"asset_id\":\"9ac11bb45069527f486c5b278be49f35\",\"public_id\":\"toeic/2020/test1/question_audio/65-67\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186911/toeic/2020/test1/question_audio/65-67.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186911/toeic/2020/test1/question_audio/65-67.mp3\",\"duration\":47.177143}', '{\"asset_id\":\"e3478cccb60ef11fad1b328d8bf4471b\",\"public_id\":\"toeic/2020/test1/question_image/65-67\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/65-67.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/65-67.webp\"}', NULL, '<p>W-Br: Carl, you cleaned all the equipment inthe laboratory last night, right? (65) I received a complaint fromone of the lab technicians this morning that I wanted to talk to youabout.</p><p>M-Cn: Really? What was the problem?</p><p>W-Br: Well, he said that the microscopelenses were dirty. (66) When you cleaned them, did you wipe them in acircular motion, like the manual indicates? If you don\'t, it couldjust spread the dirt around.</p><p>M-Cn: Oh, you know i think I might have donethat the wrong way. Sorry about that.</p><p>W-Br: It\'s OK, other people have made thatsame mistake. (67) I\'d better copy that page in the manual and postit in the lab for all the staff.</p><p>W-Br: Carl, bạn đã làm sạch tất cả các thiết bị trong phòng thí nghiệm tối qua, phải không?&nbsp;(65) Tôi đã nhận được một khiếu nại từ một trong những kỹ thuật viên phòng thí nghiệm sáng nay mà tôi muốn nói chuyện với bạn.&nbsp;</p><p>M-Cn: Thật sao?&nbsp;Có vấn đề gì thế?&nbsp;</p><p>W-Br: Chà, anh ấy nói rằng ống kính hiển vi bị bẩn.&nbsp;(66) Khi bạn làm sạch chúng, bạn có lau chúng theo chuyển động tròn, như hướng dẫn sử dụng không?&nbsp;Nếu bạn không, nó chỉ có thể phát tán bụi bẩn xung quanh.&nbsp;</p><p>M-Cn: Ồ, bạn biết đấy, tôi nghĩ rằng tôi có thể đã làm điều đó sai cách.&nbsp;Xin lỗi vì điều đó.&nbsp;</p><p>W-Br: Không sao, những người khác cũng mắc lỗi tương tự.&nbsp;(67) Tôi nên sao chép trang đó trong hướng dẫn và đăng nó trong phòng thí nghiệm cho tất cả nhân viên.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(13, '68-70', '{\"asset_id\":\"36709de3bcb2f45319a7d03ff61df34e\",\"public_id\":\"toeic/2020/test1/question_audio/68-70\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186909/toeic/2020/test1/question_audio/68-70.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186909/toeic/2020/test1/question_audio/68-70.mp3\",\"duration\":42.840816}', '{\"asset_id\":\"96158630d26e379a7e26522d8950962c\",\"public_id\":\"toeic/2020/test1/question_image/68-70\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/68-70.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/68-70.webp\"}', NULL, '<p>M-Cn: Hi, Sandra. (68) This informationpacket contains statistics about our sales performance so far thisyear. Take a look at this page-—it has the sales figures for ourhigh-end tires for the first quarter.</p><p>W-Am: Hmm... Interesting. The Z150 is ournewest car tire, right? And (69) we sold 35,000 of them in one monththis quarter! What happened that month?</p><p>M-Cn: (70) We offered a discount to cardealers that bought more than 1,000 tires. It was extremelyeffective. When we ended the deal, sales went down a little bit, sowe\'re offering it again this month.</p><p>M-Cn: Xin chào, Sandra.&nbsp;(68) Gói thông tin này chứa số liệu thống kê về hiệu suất bán hàng của chúng ta trong năm nay.&nbsp;Hãy xem trang này - nó có số liệu bán hàng cho lốp xe cao cấp của chúng ta trong quý đầu tiên.&nbsp;</p><p>W-Am: Hmm ... Thú vị.&nbsp;Z150 là lốp xe mới nhất của chúng ta, phải không?&nbsp;Và (69) chúng ta đã bán được 35.000 lốp đó trong một tháng trong quý này! Chuyện gì đã xảy ra trong tháng đó?&nbsp;</p><p>M-Cn: (70) Chúng ta giảm giá cho các đại lý xe hơi đã mua hơn 1.000 lốp xe.&nbsp;Nó cực kỳ hiệu quả.&nbsp;Khi chúng ta kết thúc thỏa thuận, doanh số giảm xuống một chút, vì vậy chúng ta sẽ cung cấp lại trong tháng này.</p>', 1000, '45ec88f1298a1d01', 1002, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(14, '71-73', '{\"asset_id\":\"b9c7ea2e0b79342f8a035f09cc22c32f\",\"public_id\":\"toeic/2020/test1/question_audio/71-73\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186913/toeic/2020/test1/question_audio/71-73.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186913/toeic/2020/test1/question_audio/71-73.mp3\",\"duration\":43.702857}', NULL, NULL, '<p><strong>M-Au</strong>: OK, let\'s get the monthly staff meetingstarted. First off, (71) this Saturday is the annual holiday parade.And as many of you knew, the parade goes right down our street. (72)It\'s always one of our busiest days... lots of people will stop byfor lunch, and the line can get quite long. So we\'ll need a few extracooks and servers, and everyone who works that day\'ll get overtimepay. Let me know soon if you\'re able to work on Saturday. Oh... and(73) I strongly recommend taking the bus or train if you can.Remember that it’ll be very difficult to park on Saturday duringthe event.</p><p><br></p><p><strong>M-Au</strong>: OK, hãy bắt đầu cuộc họp nhân viên hàng tháng.&nbsp;Trước hết, (71) thứ bảy này là cuộc diễu hành ngày lễ hàng năm.&nbsp;Và như nhiều bạn đã biết, cuộc diễu hành đi ngay qua đường của chúng ta.&nbsp;(72) Nó luôn luôn là một trong những ngày bận rộn nhất của chúng ta ... rất nhiều người sẽ ghé qua để ăn trưa, và dòng người có thể khá dài.&nbsp;Vì vậy, chúng ta sẽ cần thêm một số đầu bếp và người phục vụ, và những người làm việc vào ngày hôm đó sẽ được trả lương ngoài giờ.&nbsp;Hãy cho tôi biết sớm nếu bạn có thể làm việc vào thứ bảy.&nbsp;Ồ ... và (73) Tôi thực sự khuyên bạn nên đi xe buýt hoặc tàu nếu bạn có thể.&nbsp;Hãy nhớ rằng rất khó để đỗ xe vào thứ bảy trong suốt sự kiện này.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(15, '74-76', '{\"asset_id\":\"6092710b58859198e326a74d54b41a83\",\"public_id\":\"toeic/2020/test1/question_audio/74-76\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/74-76.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/74-76.mp3\",\"duration\":39.68}', NULL, NULL, '<p>M-Cn: Hi, Jamie. (74) I really like thesuggestion you gave at yesterday\'s staff meeting for promoting ourelectronics store. (75) I think holding a photography contest is agreat idea, especially since we mainly sell cameras and cameraequipment. (75) There are several things we\'d have to do to preparefor it, though, like decide on a submission deadline and outline thebasic rules for the contest. We could even consider offering a prizefor the first—place winner. Let\'s meet sometime this week to getstarted. (76) I\'ll take a look at our schedules this morning and booka time for us to get together.</p><p><br></p><p>M-Cn: Xin chào, Jamie.&nbsp;(74) Tôi thực sự thích đề nghị mà bạn đưa ra tại cuộc họp nhân viên hôm qua cho việc quảng bá cửa hàng điện tử của chúng ta.&nbsp;(75) Tôi nghĩ tổ chức một cuộc thi nhiếp ảnh là một ý tưởng tuyệt vời, đặc biệt vì chúng ta chủ yếu bán máy ảnh và thiết bị máy ảnh.&nbsp;(75) Tuy nhiên, có một số điều chúng ta phải làm để chuẩn bị cho nó, tuy nhiên, như quyết định thời hạn nộp bài và phác thảo các quy tắc cơ bản cho cuộc thi. Chúng ta thậm chí có thể xem xét việc cung cấp một giải thưởng cho người thắng cuộc đầu tiên. Hãy gặp nhau tuần này để bắt đầu.&nbsp;(76) Tôi sẽ xem lịch trình của chúng ta sáng nay và đặt thời gian để chúng ta gặp nhau.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(16, '77-79', '{\"asset_id\":\"d70cc72240c6717dae98f89691f6d021\",\"public_id\":\"toeic/2020/test1/question_audio/77-79\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/77-79.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/77-79.mp3\",\"duration\":45.270204}', NULL, NULL, '<p>W-Br: OK everyone, before you head outto the factory floor this morning to start your shifts, I have abrief announcement. As most of you know, (77) the new conveyor beltis now installed and up and running. (78) This new conveyor belt isvery similar to the older model, except it\'s twice as fast as the oldone. This means that our factory can now move double the number ofunits per hour. Clearly, this is a big improvement in productionspeed. However, it could also be a challenge for us to watch out forproduction errors. So, (79) you\'re all required to watch a shorttraining video this morning before starting work.</p><p><br></p><p>W-Br: OK mọi người, trước khi bạn ra nhà máy sáng nay để bắt đầu ca làm việc của mình, tôi có một thông báo ngắn gọn.&nbsp;Như hầu hết các bạn đều biết, (77) băng chuyền mới hiện đã được cài đặt và hoạt động. (78) Băng chuyền mới này rất giống với mô hình cũ, ngoại trừ nó nhanh gấp đôi so với băng chuyền cũ.&nbsp;Điều này có nghĩa là nhà máy của chúng ta hiện có thể di chuyển gấp đôi số đơn vị mỗi giờ.&nbsp;Rõ ràng, đây là một cải tiến lớn về tốc độ sản xuất.&nbsp;Tuy nhiên, nó cũng có thể là một thách thức đối với chúng ta để đề phòng các lỗi sản xuất.&nbsp;Vì vậy, (79) tất cả các bạn cần phải xem một video đào tạo ngắn vào sáng nay trước khi bắt đầu công việc.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(17, '80-82', '{\"asset_id\":\"0b02bbf72d2446b0376e6fadc449b734\",\"public_id\":\"toeic/2020/test1/question_audio/80-82\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/80-82.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/80-82.mp3\",\"duration\":36.780408}', NULL, NULL, '<p>W-Am: Hello, Kwang-Ho. Listen, I hate tobother you after you\'ve left the office for the day, but (80) I justtook a look at the materials for the health insurance orientationwe\'re doing for our new employees on Wednesday morning. (81) Andrewas supposed to finish preparing the new employee benefits packets,but he\'s been out sick, so they\'re not done. I know you\'re going tobe busy, but I don\'t have any appointments tomorrow. I do have acouple of questions about some of the materials, though, so (82) giveme a call back, thanks.</p><p><br></p><p>W-Am: Xin chào, Kwang-Ho. Nghe này, tôi không muốn làm phiền bạn sau khi bạn đã rời văn phòng, nhưng (80) tôi mới xem các tài liệu về định hướng bảo hiểm y tế mà chúng ta đang làm cho nhân viên mới của chúng ta vào sáng Thứ Tư.&nbsp;(81) Andre được giao phải hoàn thành việc chuẩn bị các gói lợi ích cho nhân viên mới, nhưng anh ta đã bị bệnh nên không hoàn thành. Tôi biết bạn sẽ bận rộn, nhưng tôi không có bất kỳ cuộc hẹn nào vào ngày mai.&nbsp;Tuy nhiên, tôi có một vài câu hỏi về một số tài liệu, vì vậy (82) hãy gọi lại cho tôi, cảm ơn.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(18, '83-85', '{\"asset_id\":\"933891ea1bba0b82f958c8c7c01b8a3f\",\"public_id\":\"toeic/2020/test1/question_audio/83-85\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186910/toeic/2020/test1/question_audio/83-85.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186910/toeic/2020/test1/question_audio/83-85.mp3\",\"duration\":42.866939}', NULL, NULL, '<p>M-Au: Do you work in the technology industry?Want to stay updated on the latest industry trends? Subscribe to ouronline magazine, Tech Now. (83) This month\'s issue is devoted towomen who are leaders in the technology field. (84) We\'re pleased topresent an exclusive interview with Erika Cliffton, the founder andCEO of Cliffton Technology Solutions. Erika gives advice for womenstarting their own businesses and shares her personal success story.(85) If you subscribe to Tech New today, you\'ll receive a free paddedcarrying case for your laptop. But hurry – the promotion expires ina week!</p><p><br></p><p>M-Au: Bạn có làm việc trong ngành công nghệ không?&nbsp;Bạn muốn cập nhật về các xu hướng công nghiệp mới nhất?&nbsp;Theo dõi tạp chí trực tuyến của chúng tôi, Tech Now. (83) Số của tháng này dành ca ngợi những phụ nữ lãnh đạo trong lĩnh vực công nghệ.&nbsp;(84) Chúng tôi rất vui mừng được giới thiệu một cuộc phỏng vấn độc quyền với Erika Cliffton, người sáng lập và CEO của Giải pháp Công nghệ Cliffton.&nbsp;Erika đưa ra lời khuyên cho phụ nữ bắt đầu kinh doanh riêng và chia sẻ câu chuyện thành công của cô ấy.&nbsp;(85) Nếu bạn đăng ký Tech New ngay hôm nay, bạn sẽ nhận được túi đựng laptop chống sốc.&nbsp;Nhưng nhanh lên - chương trình khuyến mãi sẽ hết hạn trong một tuần!</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(19, '86-88', '{\"asset_id\":\"ab30bd8af141e0708d88b8115a07b659\",\"public_id\":\"toeic/2020/test1/question_audio/86-88\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/86-88.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/86-88.mp3\",\"duration\":46.524082}', NULL, NULL, '<p>W-Am: (86) This is Health on the Go, a weeklybroadcast that gives you advice about your eating habits. Todaywe\'re talking about salt. Who\'s heard that salt is not good for you?Well... (87) this negative view of salt is surprising because it\'ssimply not true. You actually do need some salt in your diet toremain healthy. But remember-salt occurs naturally in most foods. soyou don\'t need to add extra salt to your diet. in fact, even fruitsand vegetables contain salt. (88) I know you\'re all interested intrying more recipes that use fruits and vegetables. We\'ll be talkingabout that on next week\'s broadcast.</p><p><br></p><p>W-Am: (86) Đây là Health on the Go, chương trình phát sóng hàng tuần cung cấp cho bạn lời khuyên về thói quen ăn uống của bạn.&nbsp;Hôm nay chúng ta sẽ nói về muối. Ai nghe nói rằng muối không tốt cho bạn?&nbsp;Chà ... (87) quan điểm tiêu cực về muối này thật đáng ngạc nhiên vì đơn giản là nó không đúng.&nbsp;Bạn thực sự cần một chút muối trong chế độ ăn uống của bạn để duy trì sức khỏe.&nbsp;Nhưng hãy nhớ - muối có tự nhiên trong hầu hết các loại thực phẩm.&nbsp;Vì vậy, bạn không cần thêm muối vào chế độ ăn uống của bạn.&nbsp;trong thực tế, ngay cả trái cây và rau quả có chứa muối.&nbsp;(88) Tôi biết tất cả các bạn đều thích thử nhiều công thức nấu ăn sử dụng trái cây và rau quả. Chúng ta sẽ nói về điều đó trong chương trình phát sóng vào tuần tới.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(20, '89-91', '{\"asset_id\":\"8ce4e9b45ce3a22fe74a5a4d87030e89\",\"public_id\":\"toeic/2020/test1/question_audio/89-91\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/89-91.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/89-91.mp3\",\"duration\":44.8}', NULL, NULL, '<p>W-Br: Welcome to the evening news. I\'m yourhost, Charlene Dawson. We\'ve got a lot of interesting stories tocover on tonight\'s program. And... (89) at the top of our list is anexciting announcement from Francisco City - where a solar-poweredairport will be built! One of the very first so|ar—powered airportsin the world! If you\'re looking for a job, (90) Nassar Builders, theconstruction firm that is building the airport, will be holding anemployment fair next month. At the fair, they\'ll interview and hireworkers for the project.(91) For more details about Nassar Builders,check the city\'s Web site.</p><p><br></p><p>W-Br: Chào mừng đến với tin tức buổi tối. Tôi là người dẫn chương trình, Charlene Dawson.&nbsp;Chúng tôi đã có rất nhiều câu chuyện thú vị để trình bày trong chương trình tối nay.&nbsp;Và ... (89) ở đầu danh sách của chúng tôi là một thông báo thú vị từ Thành phố Francisco - nơi sẽ xây dựng một sân bay hoạt động bằng năng lượng mặt trời!&nbsp;Một trong những sân bay đầu tiên được cung cấp trên thế giới!&nbsp;Nếu bạn đang tìm kiếm một công việc, (90) Nassar Builders, công ty xây dựng sẽ xây dựng sân bay, sẽ tổ chức hội chợ việc làm vào tháng tới.&nbsp;Tại hội chợ, họ sẽ phỏng vấn và thuê nhân công cho dự án.(91) Để biết thêm chi tiết về Nhà xây dựng Nassar, hãy kiểm tra trang web của thành phố.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(21, '92-94', '{\"asset_id\":\"dd0fb0c258d199f76c8465ac2104c332\",\"public_id\":\"toeic/2020/test1/question_audio/92-94\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/92-94.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/92-94.mp3\",\"duration\":43.180408}', NULL, NULL, '<p>M-Cn: Hi, everyone. My name is Raul Bautistaand this is History with Raul, the weekly podcast where weinvestigate little—known historical facts that have had a hugeimpact on today\'s world. (92) Today we\'ll be discussing a topicfrom art history. We\'ll hear about the mysterious disappearance ofsome paintings from a museum in seventeenth—century Europe. (93)Professor Ignacio Ortega from Westland University will explain whathappened. But before we speak to Professor Ortega—p|ease remember,this program is only made possible by the financial support of ourmembers. (94)Visit historywithraul.org today.</p><p><br></p><p>M-Cn: Xin chào, mọi người.&nbsp;Tôi là Raul Bautista và đây là Lịch sử với Raul, podcast hàng tuần nơi chúng tôi điều tra các sự kiện lịch sử ít được biết đến có ảnh hưởng lớn đến thế giới ngày nay.&nbsp;(92) Hôm nay chúng ta sẽ thảo luận về một chủ đề từ lịch sử nghệ thuật.&nbsp;Chúng ta sẽ nghe về sự biến mất bí ẩn của một số bức tranh từ một bảo tàng ở thế kỷ thứ mười bảy Châu Âu.(93) Giáo sư Ignacio Ortega từ Đại học Westland sẽ giải thích những gì đã xảy ra.&nbsp;Nhưng trước khi chúng ta nói chuyện với Giáo sư Ortega, hãy nhớ, chương trình này chỉ được thực hiện bởi sự hỗ trợ tài chính bởi các thành viên của chúng ta.&nbsp;(94) Truy cập historywithraul.org ngày hôm nay.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(22, '95-97', '{\"asset_id\":\"7e56ca7545d9d9ff2dae0491b495751b\",\"public_id\":\"toeic/2020/test1/question_audio/95-97\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/95-97.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/95-97.mp3\",\"duration\":34.821224}', '{\"asset_id\":\"34c41fa6be18b2904c20cc8d8e533313\",\"public_id\":\"toeic/2020/test1/question_image/95-97\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/95-97.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/95-97.webp\"}', NULL, '<p>W-Am: Welcome back, everyone. At tonight\'ssession, (95) we\'ll pick up where we left off and go right into adiscussion of the different types of interviews—in person, byphone. et cetera. (96) After a brief break, I\'ll split you into smallgroups so you can practice being in an actual interview situation.I\'ll walk around the room and listen to each group in order to giveyou individual feedback. Now, (97) before we start, please sign yourname on the attendance sheet on my desk.</p><p><br></p><p>W-Am: Chào mừng mọi người trở lại. Tại phiên họp tối nay, (95) chúng ta sẽ tiếp tục ở chỗ hôm trước và thảo luận về các loại phỏng vấn khác nhau, trực tiếp qua điện thoại ..v.v.&nbsp;(96) Sau thời gian nghỉ ngắn, tôi sẽ chia bạn thành các nhóm nhỏ để bạn có thể thực hành trong một tình huống phỏng vấn thực tế.&nbsp;Tôi sẽ đi quanh phòng và lắng nghe từng nhóm để đưa ra phản hồi cá nhân.&nbsp;Bây giờ, (97) trước khi chúng ta bắt đầu, vui lòng ký tên của bạn trên tờ điểm danh trên bàn của tôi.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(23, '98-100', '{\"asset_id\":\"613342d3debaefff167864eb070bc138\",\"public_id\":\"toeic/2020/test1/question_audio/98-100\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186958/toeic/2020/test1/question_audio/98-100.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186958/toeic/2020/test1/question_audio/98-100.mp3\",\"duration\":38.034286}', '{\"asset_id\":\"5231ca3f24e126fab716e319cb2908f9\",\"public_id\":\"toeic/2020/test1/question_image/98-100\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/98-100.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/98-100.webp\"}', NULL, '<p><strong>M-Au</strong>: Thanks for attending this planning meeting for the new neighborhood garden. I\'m Chao, and (98) I\'m coordinating this project. Here\'s the layout for the new garden. We\'ll mostly be planting vegetables, but we will have a herb garden, too, and were going to plant that first. (99) The herbs are going to go in the plot between the picnic area and the toolshed. Also, (100) I need volunteers to help me on Saturday. I\'d like to put up a fence around the perimeter of the garden. The wood for the fence will be delivered that morning.</p><p><br></p><p><strong>M-Au</strong>: Cảm ơn bạn đã tham dự cuộc họp lập kế hoạch này cho khu vườn mới. Tôi là Chao và (98) Tôi đang điều phối dự án này.&nbsp;Đây là cách bố trí cho khu vườn mới.&nbsp;Chúng ta chủ yếu sẽ trồng rau, nhưng chúng ta cũng sẽ có một khu vườn thảo dược và sẽ trồng cây đó trước. (99) Các loại thảo dược sẽ đi vào xen giữa khu dã ngoại và nhà để dụng cụ.&nbsp;Ngoài ra, (100) tôi cần tình nguyện viên giúp tôi vào thứ bảy.&nbsp;Tôi muốn dựng một hàng rào xung quanh chu vi của khu vườn. Gỗ cho hàng rào sẽ được giao vào sáng hôm đó.</p>', 1000, '42252db43b18e24e', 1003, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(24, '131-134', NULL, NULL, '<p>Lakeview Railway Onboard Bicycle Policy</p><p><br></p><p>Would you like to use your bicycle to explore the Lakeview Corridor Scenic Area? Our trains have the (131)— you need to safely transport your bike. When booking your ticket, just remember that reservations - (132) for both you and your bicycle. Reserve your bicycle spot (133)—. There are a limited number of storage racks on each train. You are responsible for stowing your bike securely.&nbsp;(134) . Lakeview Railway does not take responsibility for bicycles lost or damaged aboard our trains.</p>', '<p>Chính sách xe đạp trên Lakeview Railway</p><p><br></p><p>Bạn có muốn sử dụng xe đạp của mình để khám phá Khu thắng cảnh Hành lang Lakeview không? Tàu của chúng tôi có&nbsp;có&nbsp;<strong>trang thiết bị&nbsp;</strong>(131) - bạn cần vận chuyển xe đạp của mình một cách an toàn. Khi đặt vé của bạn, chỉ cần nhớ rằng đặt chỗ - (132) cho cả bạn và xe đạp của bạn. Đặt chỗ xe đạp của bạn&nbsp;<strong>sớm</strong>&nbsp;(133) -. Có một số lượng hạn chế của kệ lưu trữ trên mỗi chuyến tàu.&nbsp;Bạn có trách nhiệm cất xe đạp an toàn.&nbsp;<strong>Bạn cũng cần mang theo khóa xe đạp riêng (134)&nbsp;</strong>. Đường sắt Viewlake không chịu trách nhiệm đối với trường hợp xe đạp bị mất hoặc hỏng trên đường tàu.</p>', 1000, 'd60c451950af3846', 1005, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(25, '135-138', NULL, NULL, '<p>Corelli’s Bakery</p><p>15 Middlemass Street</p><p>Youngstown, Ohio 44515</p><p>Dear Valued Customer:</p><p>For the last three years we have charged the same wholesale prices for our baked goods, including cakes, pies, cookies, and brownies. We regret that sharply rising prices for our raw ingredients, such as sugar and fruit, have forced us to raise our prices by 5 percent —(135)— August 1. We have made every attempt to avoid this price increase. - (136)- , we refuse to compromise on the quality of our products. Using the best ingredients available will allow us to provide the delicious desserts your restaurant guests have come to expect. —(137)-—. We appreciate your -(138)- and look forward to continuing to serve you.</p><p>Sincerely,</p><p>Tony Corelli, Owner</p>', '<p>Bánh mì Corelli</p><p>15 đường Middlemass</p><p>Youngstown, Ohio 44515</p><p>Kính gửi quý khách hàng</p><p>Trong ba năm qua, chúng tôi đã tính giá bán buôn tương tự cho các sản phẩm nướng của chúng tôi, bao gồm bánh, bánh nướng, bánh quy và bánh brownies. Chúng tôi rất tiếc rằng giá tăng mạnh đối với các thành phần thô của chúng tôi, chẳng hạn như đường và trái cây, đã buộc chúng tôi tăng giá lên 5%&nbsp;&nbsp;<strong>hiệu lực từ (</strong>135) - ngày 1 tháng 8. Chúng tôi đã cố gắng hết sức để tránh việc tăng giá này.&nbsp;&nbsp;<strong>Tuy nhiên</strong>&nbsp;(136), chúng tôi từ chối thỏa hiệp về chất lượng sản phẩm của chúng tôi. Sử dụng các nguyên liệu tốt nhất có sẵn sẽ cho phép chúng tôi cung cấp các món tráng miệng ngon mà khách hàng của bạn đã mong đợi. -<strong>Chúng tôi tin rằng bạn sẽ thấy những sản phẩm của chúng tôi thật tuyệt.&nbsp;</strong>(137). Chúng tôi đánh giá cao&nbsp;<strong>sự hỗ trợ</strong>&nbsp;(138) của bạn&nbsp;và mong muốn tiếp tục phục vụ bạn.</p><p>Trân trọng,</p><p><br></p><p>Tony Corelli, Chủ sở hữu</p>', 1000, 'd60c451950af3846', 1005, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(26, '139-142', NULL, NULL, '<p>To: Noora Abadi</p><p>From: Alexis Palmer</p><p>Subject: Informational interview</p><p>Date: 4 February</p><p>Dear Ms. Abadi:</p><p>Thank you for taking the time to meet with me yesterday about careers in the aerospace industry. Your -139— were helpful and have inspired me to seek additional work experience in the field before I apply to graduate school.</p><p>I will consult the Web sites you recommended for job opportunities. As you also suggested, I will —140 — a membership in the Eastern Aeronautics Professional Association. - 141 -. I appreciate the information you shared about the organization’s conference at the end of the month.</p><p>Thank you again for your -142- assistance.</p><p>Sincerely,</p><p>Alexis Palmer</p>', '<p>Tới: Noora Abadi</p><p>Từ: Alexis Palmer</p><p>Chủ đề: Phỏng vấn thông tin</p><p>Ngày: 4 tháng 2</p><p>Kính gửi bà Abadi:</p><p>Cảm ơn bạn đã dành thời gian gặp tôi hôm qua để nói về sự nghiệp trong ngành hàng không vũ trụ.&nbsp;<strong>Sự am hiểu</strong>&nbsp;(139) của bạn vô cùng hữu ích và đã truyền cảm hứng cho tôi kiếm thêm kinh nghiệm làm việc trong&nbsp;lĩnh vực này&nbsp;trước khi tôi nộp đơn vào trường sau đại học.</p><p>Tôi sẽ tham khảo các trang web bạn đề nghị cho cơ hội việc làm. Như bạn cũng đã đề xuất, tôi sẽ xem xét (140) làm một thành viên trong Hiệp hội chuyên nghiệp hàng không phương đông.&nbsp;<strong>Tôi mong muốn được kết nối với các chuyên gia khác trong lĩnh vực này (</strong>141). Tôi đánh giá cao thông tin mà bạn đã chia sẻ về hội nghị tổ chức vào cuối tháng.</p><p>Một lần nữa, cám ơn bạn vì đã&nbsp;<strong>hào phóng (142)&nbsp;</strong>&nbsp;<strong>giúp đỡ</strong>.</p><p>Trân trọng,</p><p>Alexis Palmer</p>', 1000, 'd60c451950af3846', 1005, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL);
INSERT INTO `group_questions` (`group_id`, `group_question_order`, `group_audio`, `group_image`, `group_text`, `group_transcript`, `test_id`, `part_id`, `question_type_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(27, '143-146', NULL, NULL, '<p>15 October</p><p>GPO Box 985</p><p>CANBERRAACT 6512</p><p>Dear Ms. Wilson,</p><p>On behalf of the Australia Wildlife Park Association, thank you for your donation of 40 AUD to our national park. ——143——. Individual contributions have helped it stay open to visitors for more than 50 years. Our goal is to keep the park system running effectively for future —144- to enjoy.</p><p>Enclosed please find a copy of our brochure, which lists various programmes --145- to benefit both park visitors and our wildlife habitats. Please consider -146- one of these programmes in the future. The money would be used wisely and would be deeply appreciated.</p><p>Sincerely,</p><p>Akosua Masika, Membership Chair</p>', '<p>15 tháng 10</p><p>Hộp GPO 985</p><p>CANBERRAACT 6512</p><p>Kính gửi bà Wilson,</p><p>Thay mặt Hiệp hội Công viên động vật hoang dã Úc, cảm ơn bạn đã đóng góp 40 AUD cho công viên quốc gia của chúng ta.&nbsp;<strong>Những người như bạn đã giúp công cuộc bảo vệ công viên cho người dân sử dụng. (</strong>143). Đóng góp cá nhân đã giúp công viên có thể mở cửa cho du khách truy đến thăm trong hơn 50 năm. Mục tiêu của chúng tôi là giữ cho hệ thống công viên hoạt động hiệu quả cho&nbsp;<strong>các</strong>&nbsp;<strong>thế hệ&nbsp;</strong>tương lai tận hưởng.</p><p>Kèm theo xin vui lòng xem một bản sao của tài liệu của chúng tôi, trong đó liệt kê các chương trình khác nhau&nbsp;<strong>được thiết kế&nbsp;</strong>(145)&nbsp;để mang lại lợi ích cho cả khách tham quan công viên và môi trường sống của các động vật hoang dã. Vui lòng xem xét&nbsp;<strong>tài trợ</strong>&nbsp;(146) một trong những chương trình này trong tương lai. Tiền sẽ được sử dụng một cách khôn ngoan và sẽ được trân trọng.</p><p>Trân trọng,</p><p>Akosua Masika, Chủ tịch thành viên</p>', 1000, 'd60c451950af3846', 1005, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(28, '147-148', NULL, NULL, '<h4>http://www.cmb.com</h4><h4><br></h4><h4>Crescent Moon Bistro</h4><p>Located along the eastern shore of Canawap Bay, the Crescent Moon Bistro is a unique venue for birthday parties, weddings, corporate gatherings, and a host of other social events. Our chefs work with you to craft a perfect menu, while our coordinators will see to it that your event is superbly organized. Rental pricing is based on the date, type of event, and number of attendees.</p><p>You are welcome to tour our facility on October 10 from 11:00 AM. to 2:00 PM. Meet with our coordinators and culinary staff, and sample items from our creative menu. Admission is free, but registration is required. We are offering 25% off on any booking made during this open house on October 10.</p>', '<p>http://www.cmb.com</p><h4>Nhà hàng Trăng lưỡi liềm</h4><p>Nằm dọc theo bờ phía đông của Vịnh Canawap, nhà hàng Crescent Moon là một nơi tụ họp độc đáo cho các bữa tiệc sinh nhật, đám cưới, họp mặt công ty và một loạt các sự kiện xã hội khác. Các đầu bếp của chúng tôi sẽ làm việc với bạn để tạo ra một thực đơn hoàn hảo, trong khi các điều phối viên của chúng tôi sẽ đảm bảo rằng sự kiện của bạn được tổ chức tuyệt vời. Giá cho thuê được dựa trên ngày, loại sự kiện và số lượng người tham dự.</p><p>Bạn được chào đón đến cơ sở của chúng tôi vào ngày 10 tháng 10 từ 11:00 sáng đến 2:00 chiều. Gặp gỡ với các điều phối viên và nhân viên ẩm thực của chúng tôi và thử các món từ thực đơn sáng tạo của chúng tôi. Việc tham dự được miễn phí, nhưng yêu cầu phải đăng ký. Chúng tôi sẽ giảm giá 25% cho bất kỳ đơn đặt trước nào được thực hiện trong ngày mở cửa nhà hàng vào ngày 10 tháng 10.</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(29, '149-150', NULL, NULL, '<p><strong>To</strong>: Processing Plant Managers</p><p><strong>From</strong>: Sunlight Sugar Executive Board</p><p><strong>Date</strong>: June 15</p><p><strong>Subject</strong>: News</p><p>We are pleased to announce that, following our strongest quarter in over three years, we were ranked as the number-two sugar distributor in the region in the June 1 edition of Sugar Industry Times. We are extremely grateful to all our employees, who helped make this possible through their hard work and dedication.</p><p>To celebrate this achievement, we would like to recognize employees with a bonus to be added to their July 15 paycheck. Plant managers at each location should inform staff at the next plant meeting on July 1. Thank you for helping us achieve our goals.</p>', '<p><strong>Kính gửi</strong>: Quản lý nhà máy chế biến</p><p><strong>Từ</strong>: Ban điều hành Sunlight Sugar</p><p><strong>Ngày</strong>: 15 tháng 6</p><p><strong>Chủ đề</strong>: Tin tức</p><p>Chúng tôi vui mừng thông báo rằng, sau quý tốt nhất của chúng ta trong hơn ba năm, chúng ta đã được xếp hạng là nhà phân phối đường số hai trong khu vực trong phiên bản ngày 1 tháng 6 của thời báo Sugar Industry Times. Chúng tôi vô cùng biết ơn tất cả các nhân viên của chúng ta, những người đã giúp thực hiện điều này thông qua sự chăm chỉ và cống hiến của họ.</p><p>Để ăn mừng thành tích này, chúng tôi muốn xác nhận rằng các nhân viên sẽ được nhận một khoản thưởng thêm vào tiền lương ngày 15 tháng 7 của họ. Quản lý nhà máy tại mỗi địa điểm nên thông báo cho nhân viên tại cuộc họp nhà máy tiếp theo vào ngày 1 tháng 7. Cảm ơn các bạn đã giúp chúng tôi đạt được mục tiêu của mình.</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(30, '151-152', NULL, NULL, '<p><strong>Ella Santos [10:02 A.M.]</strong></p><p>Good morning. I purchased two tickets to Friday night’s performance. However, my business trip was rescheduled, and I won’t be in London on Friday. Can I get a refund for this purchase?</p><p><strong>Mai Tong, Customer Service [10:04 A.M.]</strong></p><p>Thank you for contacting us. Unfortunately, the Mosella Palladium’s policies do not allow refunds. We offer exchanges for tickets of equal or lesser value. You can view our entire season, which has a variety of music, dance, and theatre, at www.mosellapalladium.co.uk.</p><p><strong>Ella Santos [10:07 A.M.]</strong></p><p>I reviewed the season schedule before contacting you. Can you switch the tickets now, or must I call your phone number? I’ve already made a selection.</p><p><strong>Mai Tong, Customer Service [10:08 A.M.]</strong></p><p>I can help with that. What would you like to see instead?</p><p><strong>Ella Santos [10:10 A.M.]</strong></p><p>I’d like two tickets to the Gaperstcin Orchestra on 22 October.</p>', '<p><strong>Ella Santos [10:02 A.M.]</strong></p><p>Xin chào. Tôi đã mua hai vé cho buổi biểu diễn đêm thứ Sáu. Tuy nhiên, chuyến công tác của tôi đã được lên lịch lại và tôi sẽ không thể ở Luân Đôn vào thứ Sáu. Tôi có thể nhận hoàn tiền cho giao dịch này không?</p><p><strong>Mai Tong, Dịch vụ khách hàng [10:04 A.M.]</strong></p><p>Cảm ơn bạn đã liên hệ với chúng tôi. Thật không may, các chính sách của Mosella Palladium không cho phép hoàn lại tiền. Chúng tôi đề nghị hoán đổi thành vé có giá trị bằng hoặc nhỏ hơn. Bạn có thể xem toàn bộ mùa giải của chúng tôi, nơi có nhiều loại âm nhạc, khiêu vũ và sân khấu, tại www.mosellapalladi.co.uk.</p><p><strong>Ella Santos [10:07 A.M.]</strong></p><p>Tôi đã xem lại lịch mùa giải trước khi liên lạc với bạn. Bạn có thể chuyển đổi vé ngay bây giờ, hay tôi phải gọi số điện thoại của bạn? Tôi đã có một lựa chọn.</p><p><strong>Mai Tong, Dịch vụ khách hàng [10:08 A.M.]</strong></p><p>Tôi có thể giúp với điều đó. Bạn muốn xem gì để thay thế?</p><p><strong>Ella Santos [10:10 A.M.]</strong></p><p>Tôi muốn hai vé xem Dàn nhạc Gaperstcin vào ngày 22 tháng 10.</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(31, '153-154', NULL, NULL, '<p>*E-mai|*</p><p><strong>To</strong>: Ted Lee ‹ted.lee@comconnecting.com›</p><p><strong>From</strong>: Agnaldo Paes ‹apaes@manosinc.com›</p><p><strong>Date</strong>: May 3</p><p><strong>Subject</strong>: Interview</p><p>Dear Mr. Lee,</p><p>Thank you for your interest in the master electrician position here at Manos Contracting, Inc. Your resume is very impressive, and I would like to schedule an in—person interview sometime next week. Does next Tuesday afternoon work for you? I am usually in the office until 6 P.M. If Tuesday is not convenient, perhaps Wednesday morning would be acceptable‘? Any time after 9 A.M. works for me. My office is on the second floor of our main building, which is located at the end of Elkton Street. Since this is only our first meeting in the interview process. I do not expect it to last longer than one hour. I look forward to hearing from you soon.</p><p>Sincerely.</p><p>Agnaldo Paes</p><p>Assistant Director of Human Resources</p><p>Manos Contracting. Inc.</p>', '<p>* E-mail *</p><p><strong>Tới</strong>: Ted Lee ‹ted.lee@comconnecting.com›</p><p><strong>Từ</strong>: Agnaldo Paes ‹apaes@manosinc.com›</p><p><strong>Ngày</strong>: 3 tháng 5</p><p><strong>Chủ đề:</strong>&nbsp;Phỏng vấn</p><p>Ông Lee thân mến,</p><p>Cảm ơn ông đã quan tâm đến vị trí thợ điện chính tại công ty Manos Contracting. Sơ yếu lý lịch của ông rất ấn tượng và tôi muốn sắp xếp một cuộc phỏng vấn trực tiếp vào tuần tới. Liệu chiều thứ ba có thuận tiện cho ông không? Tôi thường ở văn phòng cho đến 6:00 giờ chiều. Nếu thứ ba không thuận tiện, có lẽ sáng thứ tư sẽ có thể chấp nhận được? Bất cứ lúc nào sau 9AM tôi đều sẵn sàng. Văn phòng của tôi ở trên tầng hai của tòa nhà chính của chúng tôi, nằm ở cuối đường Elkton. Vì đây là lần đầu tiên của chúng ta gặp gỡ trong quá trình phỏng vấn. Tôi không mong đợi nó sẽ kéo dài hơn quá một giờ đồng hồ. Tôi mong muốn được nghe tin từ ông sớm.</p><p>Trân trọng.</p><p>Agnaldo Paes.</p><p>Trợ lý giám đốc nhân sự</p><p>Hợp đồng Manos. Inc.</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(32, '155-157', NULL, NULL, '<table class=\"table table-bordered\"><tbody><tr><td colspan=\"4\">◁ ▷ ↻ &nbsp;http://www.mazullospizza.com<br></td></tr><tr><td>Home</td><td><b><u>About</u></b></td><td>Our Ingredients</td><td>Order Online</td></tr><tr><td colspan=\"4\"><h5 id=\"mazullo’s-deep-dish-pizza\"><b>Mazullo’s Deep-Dish Pizza</b></h5><p>Get a taste of the best pizza in Chicago!</p><p>We have been serving authentic deep-dish Chicago-style pizza since Tonia Mazullo opened the original restaurant in a humble shop in Bridgeport. Thirty-five years later, her children and grandchildren continue to craft delectable pizzas using traditional Mazullo -family dough and tomato sauce recipes.</p><p>We offer dine-in, carryout, and delivery service within three miles of our locations.</p><p>- All pizzas are made fresh to order and include your choice of three toppings. Every pizza is served with a large beverage and our famous garlic rolls.</p><p>- A variety of salads and pastas make optional side dishes.</p><p>- All vegetable toppings are local, organic, and farm-to-table.                           </p><p>Click on a location to get directions. phone numbers, and restaurant hours.</p></td></tr><tr><td>?<u>Bridgeport</u></td><td>?<u>Lincoln Park</u></td><td>?<u>Edgewater</u></td><td>?<u>Avondale</u></td></tr></tbody></table>', '<table class=\"table table-bordered\"><tbody><tr><td colspan=\"4\">◁&nbsp;▷&nbsp;↻&nbsp; http://www.mazullospizza.com<br></td></tr><tr><td>Trang chủ</td><td><b><u>Giới thiệu</u></b></td><td>Nguyên liệu</td><td>Đặt hàng</td></tr><tr><td colspan=\"4\"><h5 id=\"pizza-deep-dish-pizza\"><b>Pizza Deep-Dish Pizza</b></h5> <p>Thưởng thức một chiếc bánh pizza ngon nhất ở Chicago!</p><p>Chúng tôi đã được phục vụ món pizza đúng kiểu&nbsp; Chicago kể từ khi Tonia Mazullo mở nhà hàng ban đầu trong một cửa hàng khiêm tốn ở Bridgeport. Ba mươi lăm năm sau, các con và cháu của bà tiếp tục chế tạo các loại pizza ngon lành bằng cách sử dụng công thức nấu bột và nước sốt cà chua Mazullo truyền thống.</p><p>Chúng tôi cung cấp món tại chỗ, mang đi, và dịch vụ giao hàng trong vòng ba dặm từ địa điểm của chúng tôi.</p><p>- Tất cả các loại pizza được làm mới khi đặt hàng với sự lựa chọn của bạn trong ba lớp phủ mặt bánh. Mỗi chiếc bánh pizza được phục vụ với một đồ uống lớn và cuốn tỏi nổi tiếng của chúng tôi.</p><p>- Một loạt các món salad và mì ống làm món ăn phụ tùy chọn.</p><p>- Tất cả các loại rau trên mặt đều là của địa phương, hữu cơ và trực tiếp từ nông trại.</p><p>Click vào vị trí để biết đường đi. số điện thoại, và giờ nhà hàng phục vụ.</p></td></tr><tr><td>?<u>Bridgeport&nbsp;</u><br></td><td>?<u>Công viên Lincoln</u><br></td><td>?<u>Edgwater</u>&nbsp;<br></td><td>?<u>Avondale</u><br></td></tr></tbody></table>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(33, '158-160', NULL, NULL, '<p><strong>Kendinburgh Transit</strong></p><p>64 Ponteland Rd</p><p>Kendinburgh, TD9 5UW</p><p><br></p><p>Callum Stevenson</p><p>42 Leicester Road</p><p>Girvaton, P24 9QS</p><p>3 January</p><p>Dear Mr. Stevenson,</p><p>&nbsp;[1] -. We are happy to have you as part of the Kendinburgh Transit team. Prior to your receiving training on the vehicle you will be assigned to, we must ﬁrst ensure that your medical documentation is up-to-date. — [2] —.</p><p>The main priority of public transport is the safety of passengers and other motorists. Your ability to safely operate a bus in city traffic and changing weather conditions depends in part on your good health. For this purpose, you will need to undergo a pre-employment physical checkup. To make an appointment, please call (0500) 555 0140. — [3] —. Your examination will be performed by a physician selected by Kendinburgh Transit, and you will not be charged for it. — [4] —. Please present the physicians report to your supervisor on your ﬁrst day.</p><p>We look forward to working with you.</p><p>Kristine Yerkes</p><p>Kendinburgh Transit</p>', '<p><strong>Vận chuyển Kendinburgh</strong></p><p>64 đường Ponteland</p><p>Kendin, TD9 5UW</p><p><br></p><p>Callum Stevenson</p><p>42 đường Leicester</p><p>Girvaton, P24 9QS</p><p>3 tháng 1</p><p>Thưa ông Stevenson,</p><p>Chúng tôi rất vui khi có ông là một phần của đội vận chuyển Kendinburgh. Trước khi bạn đi đào tạo về chiếc xe sẽ được phân công, trước tiên chúng tôi phải đảm bảo rằng tài liệu y tế của bạn đã được cập nhật - [2] -.</p><p>Ưu tiên chính của giao thông công cộng là sự an toàn của hành khách và những người lái xe máy. Khả năng của bạn để vận hành xe buýt an toàn trong giao thông thành phố và điều kiện thời tiết luôn thay đổi phụ thuộc một phần vào sức khỏe của bạn. Đối với mục đích này, bạn sẽ cần phải trải qua kiểm tra thể chất trước khi đi làm. Để đặt hẹn, xin vui lòng gọi (0500) 555 0140. - [3] -. Việc kiểm tra của bạn sẽ được thực hiện bởi một bác sĩ được lựa chọn bởi Kendinburgh Transit và bạn sẽ không bị tính phí cho việc này. - [4] -. Vui lòng trình các báo cáo của bác sĩ cho người giám sát của bạn vào ngày đầu tiên đi làm.</p><p>Chúng tôi mong được làm việc với bạn.</p><p>Kristine Yerkes</p><p>Kendinburgh Transit</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(34, '161-163', NULL, NULL, '<p><strong>A Changing of the Guard at Rolidge Motors</strong></p><p>by Nathan Kekana</p><p>DURBAN—Rolidge Motors has announced that Cara Walters will be the next CEO of the Durban—based company. Ms. Walters succeeds Thomas Hsing, who has served in the role for fifteen years and is retiring. Most recently, Ms. Walters was executive vice president for Cermak &amp; Holden Ltd., which she helped to grow into one of the largest electronics firms in South Africa.</p><p>This marks Ms. Walters’ return to Rolidge Motors, where she began her career after graduating from university. She completed the Rolidge Leadership Programme and stayed for seven years before moving on to Cermak &amp; Holden.</p><p>“Ms. Walters has both the leadership experience and inside knowledge of Rolidge Motors to make her tenure here successful.” remarked Mr. Hsing. “We are excited to have Ms. Walters join us.” added Matilde Bekwa, Rolidge Motors’ chairman of the board. “Her work at Cermak &amp; Holden has been remarkable, and we look forward to benefiting from her visionary leadership.\"</p>', '<p><strong>Thay đổi người Bảo hộ tại Rolidge Motors</strong></p><p>tác giả Nathan Kekana</p><p>DURBAN, Rolidge Motors đã thông báo rằng Cara Walters sẽ là CEO tiếp theo của công ty có trụ sở tại Durban. Bà Walters kế nhiệm Thomas Hsing, người đã đảm nhiệm vai trò này trong nhiều năm và đang nghỉ hưu. Gần đây nhất, Bà Walters là phó chủ tịch điều hành của Cermak &amp; Holden Ltd., mà bà đã giúp phát triển thành một trong những công ty điện tử lớn nhất ở Nam Phi.</p><p>Điều này đánh dấu sự trở lại Rolidge Motors của bà Walters, nơi bà bắt đầu sự nghiệp sau khi tốt nghiệp đại học. Bà đã hoàn thành chương trình Lãnh đạo Rolidge và ở lại bảy năm trước khi chuyển sang Cermak &amp; Holden.</p><p>\"Bà Walters có cả kinh nghiệm lãnh đạo và kiến ​​thức thực tế về Rolidge Motors để giúp nhiệm kỳ của bà thành công ở đây.\" ông Hsing nhận xét. \"Chúng tôi rất vui mừng khi có cô Walters tham gia cùng chúng tôi\" Matilde Bekwa, chủ tịch hội đồng quản trị của Rolidge Motors, bổ sung. Công việc của cô ấy tại Cermak &amp; Holden rất đáng chú ý và chúng tôi mong muốn được hưởng lợi từ sự lãnh đạo có tầm nhìn của cô ấy. \"</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(35, '164-167', NULL, NULL, '<p>*E-mail*</p><p><strong>To</strong>:&nbsp;&nbsp;skim@jigyeapartments.com</p><p><strong>From</strong>: larue@waterservicesorg</p><p><strong>Subject</strong>:&nbsp;Water Shut-off</p><p><strong>Date</strong>:&nbsp;7 January</p><p>Dear Mr. Kim,</p><p>Because of a maintenance project, the water to Jigye Apartments will be turned off for several hours next Wednesday, 12 January. The interruption will begin at 11:00 A.M. Water service will be restored by 5:00 P.M. Please inform all of your buildings tenants in advance about the interruption, as well as these general guidelines:</p><p>1. After the water is turned back on, air in the pipes may cause sudden bursts of water. You can fix this problem by running water slowly at first.</p><p>2. For any other issues that occur after water service is returned, call our Customer Service desk at the number listed on our Web site for your speciﬁc area.</p><p>3. Maintenance workers do their best to work quickly and ﬁnish as scheduled.</p><p>This service interruption is necessary to improve the quality of your water service in the future. We apologize for any inconvenience and thank you for your patience.</p><p>Best regards,</p><p>Pierrick de la Rue</p>', '<p>*E-mail*</p><p><strong>Tới</strong>:&nbsp;skim@jigyeapousing.com</p><p><strong>Từ</strong>: larue@Waterserviceorg</p><p><strong>Chủ đề</strong>: Tắt nước</p><p><strong>Ngày</strong>: 7 tháng 1</p><p>Kính gửi ông Kim,</p><p>Vì một dự án bảo trì, nước đến khu căn hộ Jigye sẽ bị tắt trong vài giờ vào thứ Tư sắp tới, ngày 12 tháng 1. Sự gián đoạn sẽ bắt đầu lúc 11:00 A.M. Dịch vụ nước sẽ được khôi phục trước 5:00 P.M. Vui lòng thông báo cho tất cả những người thuê nhà của ông trước về sự gián đoạn, cũng như các hướng dẫn chung sau:</p><p>1. Sau khi nước được bật trở lại, không khí trong đường ống có thể gây ra những vụ nổ nước đột ngột. Các bạn có thể khắc phục vấn đề này bằng cách để nước chảy chậm lúc đầu.</p><p>2. Đối với bất kỳ vấn đề nào khác xảy ra sau khi dịch vụ nước hoạt động trở lại, hãy gọi cho bàn Dịch vụ khách hàng của chúng tôi theo số được liệt kê trên trang web của chúng tôi cho khu vực cụ thể của các bạn.</p><p>3. Nhân viên bảo trì làm hết sức để làm việc nhanh chóng và hoàn thành đúng như lịch trình.</p><p>Sự gián đoạn dịch vụ này là cần thiết để cải thiện chất lượng dịch vụ nước của bạn trong tương lai. Chúng tôi xin lỗi vì sự bất tiện này và cảm ơn vì sự kiên nhẫn của các bạn.</p><p>Trân trọng,</p><p>Pierrick de la Rue</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(36, '168-171', NULL, NULL, '<p><strong>To</strong>: South Street Bank staff</p><p><strong>From</strong>: William Rees-Yates, Chief Executive Officer</p><p><strong>Date</strong>: May 12</p><p>I am pleased to announce that our bank is expanding. Thanks to our creative marketing and award-winning customer service, the demand for our services has been growing. — [1] —. We will therefore be opening a branch in Leesburg this year.</p><p>Although the new branch will not be in operation until July 1, it is already virtually ready to open. — [2] —. There remain, however, a couple of job openings to be filled that can be viewed at www.southstreetbank.com/jobs. If any of our current staff are interested in transferring to the Leesburg branch, we encourage you to review the Vacancies soon and apply at the Web site listed above. Please contact Human Resources with any questions. — [3] —.</p><p>Meanwhile, our business continues to thrive and grow in other ways. — [4] —. We have recently been nominated for the Business of the Year award by the Chamber of Commerce. This is a signiﬁcant achievement, due in no small part to the dedicated work of our outstanding team. On behalf of our management team, thank you Very much and congratulations.</p>', '<p><strong>Kính gửi</strong>: nhân viên ngân hàng South Street</p><p><strong>Từ</strong>: William Rees-Yates, Giám đốc điều hành</p><p><strong>Ngày</strong>: 12 tháng 5</p><p>Tôi vui mừng thông báo rằng ngân hàng của chúng ta đang mở rộng. Nhờ việc tiếp thị sáng tạo và dịch vụ khách hàng đã giành giải thưởng của chúng ta, nhu cầu về dịch vụ của chúng ta&nbsp;ngày càng gia tăng. - [1] -. Do đó, chúng ta&nbsp;sẽ mở chi nhánh tại Leesburg trong năm nay.</p><p>Mặc dù chi nhánh mới sẽ không hoạt động cho đến ngày 1 tháng 7, nhưng nó hầu như đã sẵn sàng để mở cửa. - [2] -. Tuy nhiên, vẫn còn một vài cơ hội việc làm cần được xem xét tại www.southstreetbank.com/jobs. Nếu bất kỳ nhân viên hiện tại nào của chúng ta&nbsp;quan tâm đến việc chuyển sang chi nhánh Leesburg, chúng tôi&nbsp;khuyến khích bạn sớm xem xét các Vị trí tuyển dụng và đăng ký tại trang web được liệt kê ở trên. Vui lòng liên hệ với bộ phận Nhân sự nếu có bất kỳ câu hỏi nào. - [3] -.</p><p>Trong khi đó, hoạt động kinh doanh của chúng ta&nbsp;tiếp tục phát triển và phát triển theo những cách khác. - [4] -. Gần đây, chúng ta&nbsp;đã được đề cử cho giải thưởng Doanh nghiệp của năm. Đây là một thành tựu đáng kể, do một phần không nhỏ trong công việc tận tụy của đội ngũ xuất sắc của chúng ta. Thay mặt nhóm quản lý chúng tôi, cảm ơn bạn rất nhiều và xin chúc mừng.</p>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(37, '172-175', NULL, NULL, '<h4>Monday, 8 May</h4><p><strong>Gabriel Li (9:10 A.M.):</strong></p><p>Good morning, everyone. I want to remind you that Larkin Landscaping will be here at Derryco tomorrow morning to remove the trees from the front parking area. My workers will block off the area before the contractor arrives, so you and your staff should plan to find parking elsewhere or use public transit.</p><p><strong>Ava Abberton (9:11 A.M.):</strong></p><p>I have a client, Jan McGonagle, who will be driving in from Belfast to meet with me at 10:00 A.M. What should I tell her? Can she contact the facilities department?</p><p><strong>Martin Beattie (9:12 AM.):</strong></p><p>There’s heavy rain in the forecast. Are you sure the tree work will go forward?</p><p><strong>Gabriel Li (9:13 A.M.):</strong></p><p>Yes, give Ms. McGonagle my mobile phone number and have her call me when she arrives. I will direct her around the back. The spots there will be reserved for visitors only.</p><p><strong>Gabriel Li (9:14 A.M.):</strong></p><p>And yes, Larkin assured me the crew comes out rain or shine.</p><p><strong>Daniel Deegan (9:15A.M.):</strong></p><p>Remember, too, that we can approve team members to work from home tomorrow. Just make sure that all conference calls are listed on the master schedule on the intranet.</p><p><strong>Gabriel Li (9:16 AM.):</strong></p><h4>Right. Thank you, all.</h4>', '<h4>Thứ hai ngày 8 tháng 5</h4><p><strong>Gabriel Li (9:10 A.M.)</strong></p><p>Chào buổi sáng mọi người. Tôi muốn nhắc bạn rằng Larkin Landscaping sẽ có mặt tại Derryco vào sáng mai để loại bỏ cây khỏi khu vực đỗ xe phía trước. Nhân viên của tôi sẽ chặn khu vực trước khi nhà thầu đến, vì vậy bạn và nhân viên của bạn nên có kế hoạch tìm chỗ đậu xe ở nơi khác hoặc sử dụng phương tiện công cộng.</p><p><strong>Ava Abberton (9:11 A.M.)</strong></p><p>Tôi có một khách hàng, Jan McGonagle, người sẽ lái xe từ Belfast đến gặp tôi lúc 10:00 A.M. Tôi nên nói gì với cô ấy? Cô ấy có thể liên hệ với bộ phận tiện ích không?</p><p><strong>Martin Beattie (9:12 A.M.)</strong></p><p>Có mưa lớn trong dự báo thời tiết. Bạn có chắc chắn công việc về cây sẽ tiến triển?</p><p><strong>Gabriel Li (9:13 A.M.)</strong></p><p>Có, hãy cho cô McGonagle số điện thoại di động của tôi và để cô ấy gọi cho tôi khi cô ấy đến. Tôi sẽ hướng dẫn cô ấy đi xung quanh ra phía sau. Các điểm đó sẽ chỉ dành riêng cho du khách.</p><p><strong>Gabriel Li (9:14 A.M.)</strong></p><p>Và vâng, Larkin đảm bảo với tôi rằng đội công nhân sẽ ra dù mưa hay nắng.</p><p><strong>Daniel Deegan (9:15 A.M.)</strong></p><p>Cũng cần nhớ rằng, chúng ta có thể chấp thuận các thành viên trong nhóm làm việc tại nhà vào ngày mai. Chỉ cần đảm bảo rằng tất cả các cuộc gọi hội nghị được liệt kê trong lịch trình tổng thể trên mạng nội bộ.</p><p><strong>Gabriel Li (9:16 AM.)</strong></p><h4>Đúng. Cảm ơn!</h4>', 1000, 'eeff3ec8219669de', 1006, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(38, '176-180', NULL, NULL, '<table class=\"table table-bordered\"><tbody><tr><td colspan=\"4\">◁ ▷ ↻ &nbsp;http://www.sunriseaerospace.co.au/companynews</td></tr><tr><td colspan=\"4\"><h4 id=\"sunrise-aerospace\">Sunrise Aerospace</h4></td></tr><tr><td>HOME</td><td><strong><u>COMPANY NEWS</u></strong></td><td>CONTACT</td><td>REVIEWS</td></tr><tr><td colspan=\"4\">We are pleased to announce that our latest design, the Suppliss Seat, will be introduced on Honshu Express’s Tokyo Osaka service route, which is scheduled to debut soon. Since last February, our design team has worked closely with Honshu Express to produce a comfortable seat that meets the most stringent safety standards. Like all our products, it is made of lightweight yet durable materials, resulting in significant fuel-cost savings over time. The prototype for the Suppliss Seat has received high marks from designers and was nominated for a Henry Design Award in January.</td></tr></tbody></table><br><p>-------------------------</p><p>*Email*</p><p><strong>To</strong>: Joseph Tama</p><p><strong>From</strong>: Yoshi Yamamoto</p><p><strong>Subject</strong>: Information</p><p><strong>Date</strong>: 18 March</p><p>Hello, Joseph,</p><p>I hope that you are well. Many thanks for your quick turnaround since we tested the product with a small group of Consumers last month. The features your team added to the initial design are perfect, particularly the optional footrests. We were also impressed with the overall style and noticed how well the seats fit in with the contemporary look of our air carrier interiors.</p><p>By the way, the Tokyo—Osaka service route will go operational at the end of April. l’ll send you the details next week so that you can post them on your Web site.</p><p>Thanks again,</p><p>Yoshi</p>', '<table class=\"table table-bordered\"><tbody><tr><td colspan=\"4\">◁ ▷ ↻ &nbsp;http://www.sunriseaerospace.co.au/companynews</td></tr><tr><td colspan=\"4\"><h4 id=\"sunrise-aerospace-1\">Sunrise Aerospace</h4><p>Bình minh hàng không vũ trụ</p></td></tr><tr><td>HOME</td><td><strong><u>TIN TỨC CÔNG TY</u></strong></td><td>LIÊN HỆ</td><td>NHẬN XÉT</td></tr><tr><td colspan=\"4\">Chúng tôi vui mừng thông báo rằng thiết kế mới nhất của chúng tôi, ghế Suppliss, sẽ được giới thiệu trên tuyến dịch vụ Tokyo Osaka của công ty&nbsp;Honshu Express, dự kiến ​​sẽ sớm ra mắt. Kể từ tháng 2 năm ngoái, nhóm thiết kế của chúng tôi đã làm việc chặt chẽ với Honshu Express để sản xuất một ghế ngồi thoải mái đáp ứng các tiêu chuẩn an toàn nghiêm ngặt nhất. Giống như tất cả các sản phẩm của chúng tôi, nó được làm bằng vật liệu nhẹ nhưng bền, giúp tiết kiệm đáng kể chi phí nhiên liệu theo thời gian. Nguyên mẫu cho ghế Suppliss&nbsp;đã nhận được đánh giá cao từ các nhà thiết kế và được đề cử cho giải thưởng thiết kế Henry vào tháng 1.</td></tr></tbody></table><br><p>-------------------------</p><p>*E-mail*</p><p><strong>Kính gửi</strong>: Joseph Tama</p><p><strong>Từ</strong>: Yoshi Yamamoto</p><p><strong>Chủ đề</strong>: Thông tin</p><p><strong>Ngày</strong>: 18 tháng 3</p><p>Xin chào, Joseph,</p><p>Tôi hi vọng là anh khỏe. Rất cám ơn sự quay vòng nhanh chóng của anh kể từ khi chúng tôi thử nghiệm sản phẩm với một nhóm nhỏ người tiêu dùng vào tháng trước. Các tính năng mà nhóm của anh thêm vào thiết kế ban đầu là hoàn hảo, đặc biệt là chỗ để chân tùy chọn. Chúng tôi cũng rất ấn tượng với phong cách tổng thể và nhận thấy các ghế ngồi phù hợp tốt với thiết kế nội thất hiện đại của hãng hàng không chúng tôi.</p><p>Nhân tiện, tuyến dịch vụ Tokyo Osaka sẽ đi vào hoạt động vào cuối tháng Tư. Tôi sẽ gửi cho bạn các chi tiết vào tuần tới để bạn có thể đăng chúng lên trang web của bạn.</p><p>Cảm ơn một lần nữa</p><p>Yoshi</p>', 1000, 'eeff3ec8219669de', 1007, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(39, '181-185', NULL, NULL, '<h4>Leasing Opportunities</h4><p>La Gardina Mall offers a unique shopping experience in a beautiful setting of landscaped gardens, courtyards, and fountains. The mall features retail shops that range from well-known chain stores to one-of-a-kind boutiques, as well as a large variety of restaurants and cafes.</p><p>With 300,000 square meters of pedestrian-only retail space. La Gardina Mall attracts more than four million visitors per year. It is a shopping and dining destination for local Bay Shore residents and tourists alike.</p><p>If you would like more information about leasing retail or restaurant space at La Gardina, please contact Cecilia Goncalves, our Leasing Administrator, at cgoncalves@lagardinacom. While most of our space is occupied by long-term lessees, a limited number of seasonal contracts (four months minimum) are available.</p><p>-------------------------</p><p>*E-mail*</p><p><strong>To</strong>: Cecilia Goncalves&nbsp;‹cgoncalves@lagardina.com›</p><p><strong>From</strong>:&nbsp;Marco Sabatini ‹msabatini@sabatinileather.com›</p><p><strong>Date</strong>: 25 March</p><p><strong>Subject</strong>:&nbsp;Retail space</p><p><strong>Attachment</strong>: ? List of products</p><p>Dear Ms. Goncalves:</p><p>As owner of Sabatini Leather Goods, I would like to express interest in a short-term leasing opportunity at La Gardina Mall.</p><p>Sabatini Leather Goods is a small company that manufactures and sells souvenir handbags and wallets. Our high-quality leather products are imprinted with the name of the tourist destination where they are sold. I have attached sortie images of our best-selling items from our most recent temporary shop in Glastonbury, where we had our best sales performance in the company’s history. We have sold our products in 24 different locations so far, all with great success.</p><p>We have been looking for a place in Bay Shore for a while, and La Gardina Mall seems to be a good fit. We would like a space of about 150 square meters for a three-month period over the summer tourism season. Could you please call me at 555-0125 so that we can discuss this matter further?</p><p>Respectfully,</p><p>Marco Sabatini</p>', '<h4>Cơ hội cho thuê</h4><p>Trung tâm mua sắm La Gardina mang đến trải nghiệm mua sắm độc đáo trong một khung cảnh tuyệt đẹp của những khu vườn, khoảng sân nhỏ và đài phun nước. Trung tâm mua sắm này có các cửa hàng bán lẻ trải rộng từ các chuỗi cửa hàng nổi tiếng đến một loạt các các cửa hàng thời trang độc đáo, cũng như nhiều nhà hàng và quán cà phê khác nhau.</p><p>Với 300.000 mét vuông không gian bán lẻ chỉ dành cho người đi bộ. La Gardina Mall thu hút hơn bốn triệu du khách mỗi năm. Đây là một địa điểm mua sắm và ăn uống cho người dân địa phương ven vịnh cũng như khách du lịch.</p><p>Nếu bạn muốn biết thêm thông tin về việc cho thuê mặt bằng bán lẻ hoặc nhà hàng tại La Gardina, vui lòng liên hệ với Cecilia Goncalves, quản lý cho thuê của chúng tôi, tại cgoncalves@lagardinacom. Trong khi hầu hết không gian của chúng tôi bị thuê bởi những người thuê dài hạn, một số lượng hạn chế các hợp đồng thời vụ (tối thiểu bốn tháng) đang có sẵn.</p><p>-------------------------</p><p>*E-mail*</p><p><strong>Tới</strong>: Cecilia Goncalves ‹cgoncalves@lagardina.com›</p><p><strong>Từ</strong>: Marco Sabatini ‹msabatini@sabatinileather.com›</p><p><strong>Ngày</strong>: 25 tháng 3</p><p><strong>Chủ đề</strong>: Không gian bán lẻ</p><p><strong>Đính kèm</strong>: ? Danh sách sản phẩm</p><p>Kính gửi bà Goncalves:</p><p>Là chủ sở hữu của Sabatini Leather Goods, Tôi muốn bày tỏ sự quan tâm đến một cơ hội cho thuê ngắn hạn tại La Gardina Mall.</p><p>Sabatini Leather Goods là một công ty nhỏ chuyên sản xuất và bán túi xách và ví lưu niệm. Các sản phẩm da chất lượng cao của chúng tôi được in tên của địa điểm du lịch nơi chúng được bán. Tôi đã đính kèm hình ảnh sắp xếp của các mặt hàng bán chạy nhất của chúng tôi từ cửa hàng tạm thời gần đây nhất của chúng tôi ở Glastonbury, nơi chúng tôi có hiệu suất bán hàng tốt nhất trong lịch sử công ty. Chúng tôi đã bán sản phẩm của chúng tôi tại 24 địa điểm khác nhau cho đến nay, tất cả đều thành công rực rỡ.</p><p>Chúng tôi đã tìm kiếm một nơi ở Bay Shore trong một thời gian, và La Gardina Mall có vẻ rất phù hợp. Chúng tôi muốn có một không gian rộng khoảng 150 mét vuông trong khoảng thời gian ba tháng trong mùa du lịch hè. Bạn có thể vui lòng gọi cho tôi theo số 555-0125 để chúng ta có thể thảo luận thêm về vấn đề này?</p><p>Trân trọng,</p><p>Marco Sabatini</p>', 1000, 'eeff3ec8219669de', 1007, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(40, '186-190', NULL, NULL, '<div><table class=\"table table-bordered\"><tbody><tr><td colspan=\"6\"><p>&nbsp;</p><p><strong><strong>TYCHE FINE CARPETS</strong>—Pleiades Collection</strong></p><p>&nbsp;</p><p>&nbsp;</p> <p>Product Availability (updated daily)</p></td></tr><tr><td><strong>Name</strong></td><td><strong>Size</strong><br>(cm)</td><td><strong>Shipping<br>Weight</strong><br>(kg)</td><td><p><strong>Quantity<br>Available</strong><br>(today)</p></td><td><strong>Quantity<br>Available</strong><br>(in 30days)</td><td><strong>Quantity<br>Available</strong><br>(in 60days)</td></tr><tr> <td>Artemis</td><td>190x280</td><td>13</td><td>30</td><td>60</td><td>0</td></tr><tr><td>Hera</td><td>190x280</td><td>14</td><td>16</td><td>20</td><td>0</td></tr><tr><td>Janus</td>td>160x230</td><td>11</td><td>0</td><td>0</td><td>20</td></tr><tr> <td>Iris</td><td>120x170</td><td>9</td><td>10</td><td>15</td><td>15</td></tr></tbody></table><p>-------------------------</p><p><strong>To</strong>: Frieda Zuckerman<br><strong>From</strong>: Miles Sorrell<br><strong>Date</strong>: February 5&nbsp;<br><strong>Subject</strong>: Logistical arrangements<br><strong>Attachment</strong>: ? Photos</p><p>Dear Ms. Zuckerman:</p><p>I regret to inform you that Tyche Fine Carpets, the supplier we selected for the carpets in The Pavel Hotel’s lobby and lounge areas, will not have our chosen pattern available until after the hotel’s anticipated opening date of March 1. Attached are photographs of several alternative selections that I believe will work well with the décor. They are all made of the same material as the previous selection, and the prices are comparable. With the grand opening less than a month away, I need a decision from you as soon as possible. Even with this last-minute change, I am certain that The Pavel Hotel will provide the ambience we have set out to create.</p><p>Thank you,<br>Miles Sorrell</p><div>-------------------------</div><div><strong>Pavel Hotel Open</strong></div><div>by Lavonne Coe</div><p>(Centerville—March 2) Former city court judge Mildred Simpson joined owner Patrice Snell yesterday to celebrate the opening of The Pavel Hotel in downtown Centerville, between the library and the visitors center. Once the city’s courthouse and Ms. Simpson’s workplace, the existing structure had been vacant for the past nine years. Now the space boasts 34 elegant rooms, an inviting lounge with a ﬁreplace, and a gorgeous lobby. An on-site cafe is expected to open next month. The interior, designed by Miles Sorrell, retains the old features of the building, such as expansive windows and high ceilings, while creating a warm and inviting space.</p><p>&nbsp;</p></div>', '<div><table class=\"table table-bordered\"> <tbody><tr> <td colspan=\"6\"><p><strong>THẢM ĐẸP TYCHE — Bộ sưu tập Pleiades</strong></p><p>Sản phẩm có sẵn (cập nhật hàng ngày)</p></td></tr><tr> <td><strong>Tên</strong></td><td><strong>Kích cỡ</strong><br> (cm)</td> <td><strong>Khối lượng<br> vận chuyển</strong><br>(kg)</td> <td> <p><strong>Số lượng<br>có</strong><br>(hôm nay)</p> </td><td><strong>Số lượng<br>có</strong><br>(trong 30 ngày)</td><td><strong>Số lượng<br>có</strong><br>(trong 60 ngày)</td></tr><tr><td>Artemis</td> <td>190x280</td><td>13</td><td>30</td> <td>60</td> <td>0</td></tr><tr><td>Hera</td><td>190x280</td><td>14</td><td>16</td><td>20</td><td>0</td> </tr><tr><td>Janus</td><td>160x230</td><td>11</td> <td>0</td><td>0</td><td>20</td></tr> <tr><td>Iris</td><td>120x170</td><td>9</td><td>10</td><td>15</td><td>15</td></tr></tbody></table><div>-------------------------</div><p><strong>Kính gửi</strong>: Frieda Zuckerman</p><p><strong>Từ</strong>: Miles Sorell</p><p><strong>Ngày</strong>: 5 tháng 2</p><p><strong>Chủ đề</strong>: Sắp xếp hậu cần</p><p><strong>Đính kèm</strong>: ? Hình ảnh</p><p>Kính gửi bà Zuckerman:</p><p>Tôi rất tiếc phải thông báo cho bà rằng Tyche Fine Carpets, nhà cung cấp chúng tôi đã chọn cho thảm trong khu vực hành lang và sảnh của khách sạn Pavel, sẽ không có mẫu đã chọn của chúng tôi cho đến sau ngày mở cửa dự kiến ​​của khách sạn vào ngày 1 tháng 3. Các hình đính kèm là một vài lựa chọn thay thế mà tôi tin rằng sẽ phù hợp với sự trang trí. Tất cả đều được làm bằng vật liệu giống như lựa chọn trước, và giá cả tương đương nhau. Với việc khai trương chưa đầy một tháng, tôi cần một quyết định từ bà càng sớm càng tốt. Ngay cả với lần thay đổi vào phút cuối này, tôi chắc chắn rằng The Pavel Hotel sẽ mang đến phong cách mà chúng ta đã đặt ra.</p><p>Cảm ơn bà,</p><p>Miles Sorell</p><div>-------------------------</div><p><strong>Mở cửa khách sạn Pavel</strong></p><p>bởi Lavonne Coe</p><p>(Centerville—ngày 2 tháng 3) Cựu thẩm phán tòa án thành phố Mildred Simpson đã cùng chủ sở hữu Patrice Snell hôm qua để ăn mừng khai trương khách sạn Pavel ở trung tâm thành phố Centerville, nằm giữa thư viện và trung tâm du khách. Một thời từng là tòa án thành phố và nơi làm việc của bà Simpson, công trình hiện tại đã bị bỏ trống trong chín năm qua. Giờ đây, nó tự hào có 34 phòng trang nhã, phòng khách hấp dẫn với lò sưởi trang trí và sảnh tuyệt đẹp. Một quán cà phê bên trong dự kiến ​​sẽ mở vào tháng tới. Nội thất, được thiết kế bởi Miles Sorrell, vẫn giữ được những nét cũ của tòa nhà, như cửa sổ mở rộng và trần nhà cao, đồng thời tạo ra một không gian ấm áp và lôi cuốn.</p></div>', 1000, 'eeff3ec8219669de', 1008, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(41, '191-195', NULL, NULL, '<p><strong>From</strong>: Optieris Office of Parking and Transportation</p><p><strong>To</strong>: All Optieris staff</p><p><strong>Date</strong>: December 20</p><p><strong>Subject</strong>: Upcoming enhancements to our shuttle bus system</p><p>In direct response to your helpful feedback, we would like to announce a number of improvements to the shuttle system that connects the Optieris campus with the Morbrook and Nesse train stations. The following changes will go into effect on January 2:</p><p>(1) A third bus will be added to our fleet to increase service frequency as well as capacity in case one bus is ever down for maintenance. Buses will now run every 15 minutes instead of 30 minutes.</p><p>(2) A second campus stop will be added. Besides the current stop at the main administration building on the east side of the Optieris campus, there will be a second stop to better accommodate all our staff.</p><p>(3) A service will be added in the evening. It will depart the Optieris campus 30 minutes later than the current last service of the day.</p><p>Thanks again for your input. For the sake of our environment, we are proud to facilitate your use of public transportation by making our shuttle bus service more convenient than ever.</p><p>&nbsp;</p><p><img src=\"191-195.png\"></p><p>-------------------------</p><p>*E-mail*</p><p><strong>From</strong>: Soﬁa Edgren</p><p><strong>To</strong>:&nbsp;Sharani Khamis ‹s.khamis@optieris.com›&nbsp;</p><p><strong>Subject</strong>:&nbsp;Applicant interview at Optieris</p><p><strong>Date</strong>:&nbsp;January 25&nbsp;</p><p>Dear Ms. Khamis,</p><p>Thanks for inviting me to an interview with Mr. Rochon next week on the Optieris campus. I am certainly excited to be a finalist for this position in quality control. I also appreciate your sending me the company shuttle bus schedule. I will take a train arriving at Nesse Station at 7:55 A.M. and then your shuttle bus upon arrival, which should get me to your West Campus at a reasonable time.</p><p>Sincerely,</p><p>Soﬁa Edgren</p>', '<p><strong>Từ</strong>: Văn phòng Optieris về băng đỗ xe và vận chuyển</p><p><strong>Kính gửi</strong>: Tất cả nhân viên của Optieris</p><p><strong>Ngày</strong>: 20 tháng 12</p><p><strong>Chủ đề</strong>: Những cải tiến sắp tới cho hệ thống xe buýt đưa đón của chúng ta</p><p>Đáp lại phản hồi hữu ích của các bạn, chúng tôi xin thông báo một số cải tiến cho hệ thống tàu kết nối khuôn viên Optieris với các ga tàu Morbrook và Nesse. Những thay đổi sau sẽ có hiệu lực vào ngày 2 tháng 1:</p><p>(1) Một chiếc xe buýt thứ ba sẽ được thêm vào đội xe của chúng ta để tăng tần suất dịch vụ cũng như công suất trong trường hợp một chiếc xe buýt không hoạt động để bảo trì. Xe buýt sẽ chạy cứ sau 15 phút thay vì 30 phút.</p><p>(2) Một điểm dừng trường thứ hai sẽ được thêm vào. Cùng với điểm dừng hiện tại tại tòa nhà hành chính chính ở phía đông của cơ sở Optieris, sẽ có một điểm dừng thứ hai để phù hợp hơn với tất cả nhân viên của chúng ta.</p><p>(3) Một dịch vụ sẽ được thêm vào buổi tối. Nó sẽ rời trường Optieris muộn hơn 30 phút so với dịch vụ cuối cùng hiện tại trong ngày.</p><p>Cảm ơn một lần nữa cho sự gớp ý của các bạn. Vì lợi ích của môi trường của chúng ta, chúng tôi tự hào trợ giúp các bạn sử dụng phương tiện giao thông công cộng bằng cách làm cho dịch vụ xe buýt đưa đón của chúng ta thuận tiện hơn bao giờ hết.</p><p>-------------------------</p><p><strong><img src=\"191-195.png\"></strong></p><p><strong>-------------------------</strong></p><p><strong>*E-mail*</strong></p><p><strong>Từ</strong>: Soﬁa Edgren</p><p><strong>Kính gửi</strong>: Sharani Khamis</p><p><strong>Chủ đề</strong>: Phỏng vấn ứng viên tại Optieris</p><p><strong>Ngày</strong>: 25 tháng 1</p><p>Thưa bà Khamis,</p><p>Cảm ơn vì đã mời tôi đến một cuộc phỏng vấn với ông Rochon vào tuần tới tại khuôn viên Optieris. Tôi chắc chắn rất vui mừng khi được vào vòng cuối cho vị trí này trong việc kiểm soát chất lượng. Tôi cũng cảm kích việc bà gửi cho tôi lịch trình xe buýt đưa đón của công ty. Tôi sẽ đi tàu đến ga Nesse lúc 7:55 A.M. và sau đó xe buýt đưa đón của bà sẽ đến, nó sẽ đưa tôi đến khu phía Tây của&nbsp;trường bà trong thời gian hợp lý.</p><p>Trân trọng,</p><p>Soﬁa Edgren</p>', 1000, 'eeff3ec8219669de', 1008, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(42, '196-200', NULL, NULL, '<div><p><img src=\"https://toeicez.com/medias/toeicfull/ets_toeic_2020_test_1/196_200.png\"></p><p>-------------------------</p><table class=\"table table-bordered\"><tbody><tr><td>◁&nbsp;▷&nbsp;↻&nbsp; http://www.uopine.com/business/bright-now-home</td></tr><tr><td><p>September 18</p><p>I used Bright Now Home’s new in-store customer pickup for the first time this week. The service was a big time-saver because my order was ready for me when I got to the store. Since I had already paid online, I didn’t have to wait in the regular line in the store.</p><p>Unfortunately, I didn’t double-check my order before I left the store. When I arrived at the house I was working on, I realized I had received only one of the two gallons of BN-101 paint I had ordered. I called the store immediately, and the manager arranged for me to pick up the missing gallon of paint at the location closest to where I was working. Also, he gave me my money back for both gallons. I will deﬁnitely use this service again!</p><p>Jesse Beeby</p></td></tr></tbody></table><p>-------------------------</p><p>*Email*</p><p><strong>To</strong>: Jesse Beeby<br><strong>From</strong>: Hattie Jones<br><strong>Date</strong>: September 19<br><strong>Subject</strong>: Online Order</p><p>Mr. Beeby,</p><p>We are glad to have served your business recently. We saw the comments you posted about us on uopine.com, and we are grateful to you. It was nice to hear that our ﬂagship location was so convenient to your work site and that you were able to pick up your missing paint there.</p><p>We stand behind our products and services and look forward to seeing you again soon.After all, the rainy season is almost here, so now is a great time to come in and get the tools you need for those upcoming roof jobs!</p><p>Hattie Jones<br>Customer Service Manager<br>Bright Now Home</p></div>', '<div><p><img src=\"https://toeicez.com/medias/toeicfull/ets_toeic_2020_test_1/196_200.png\"></p><p>-------------------------</p><table class=\"table table-bordered\"> <tbody><tr><td>◁&nbsp;▷&nbsp;↻&nbsp;&nbsp;http://www.uopine.com/business/bright-now-home</td></tr><tr><td><p>Ngày 18 tháng 9</p><p>Tuần này, lần đầu tiên tôi sử dụng dịch vụ mới chuẩn bị sẵn hàng tại cửa hàng của Bright Now Home.&nbsp;Dịch vụ này là một công cụ tiết kiệm nhiều thời gian vì đơn hàng của tôi đã sẵn sàng cho tôi khi tôi đến cửa hàng. Do&nbsp;tôi đã thanh toán trực tuyến, tôi đã không phải chờ trong hàng như bình thường trong cửa hàng.</p><p>Thật không may, tôi đã không kiểm tra lại đơn đặt hàng trước khi tôi rời khỏi cửa hàng. Khi tôi đến ngôi nhà tôi đang làm việc, tôi nhận ra rằng tôi chỉ nhận được một trong hai gallon sơn BN-101 tôi đã đặt hàng. Tôi gọi cho cửa hàng ngay lập tức, và người quản lý sắp xếp tôi đến lấy gallon sơn còn thiếu ở vị trí gần nơi tôi đang làm việc nhất. Ngoài ra, anh ấy đã trả lại tiền cho tôi cho cả hai gallon. Tôi chắc chắn sẽ sử dụng dịch vụ này một lần nữa!</p><p>Jesse Beeby</p> </td></tr></tbody></table><p>-------------------------</p><p>*E-mail*</p><p><strong>Kính gửi</strong>: Jesse Beither<br><strong>Từ</strong>: Hattie Jones<br><strong>Ngày</strong>: 19 tháng 9<br><strong>Chủ đề</strong>: Đặt hàng trực tuyến</p><p>Ông Beither,</p><p>Chúng tôi rất vui vì đã được phục vụ công việc của bạn gần đây. Chúng tôi đã thấy những bình luận bạn đăng về chúng tôi trên uopine.com và chúng tôi rất biết ơn bạn. Thật vui khi biết rằng vị trí đắc địa của chúng tôi rất thuận tiện cho địa điểm làm việc của bạn và bạn có thể lấy sơn bị thiếu ở đó.</p><p>Chúng tôi luôn hỗ trợ các sản phẩm và dịch vụ của chúng tôi và mong sớm gặp lại bạn. Rốt cuộc, mùa mưa đã gần đến, vì vậy bây giờ là thời điểm tuyệt vời để đến và mua các công cụ bạn cần cho những công việc trên mái nhà sắp tới!</p><p>Hattie Jones<br>Quản lý dịch vụ khách hàng<br>Bright Now Home</p></div>', 1000, 'eeff3ec8219669de', 1008, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL);
