INSERT INTO `questions` (`question_id`, `question_order`, `question_audio`, `question_image`, `question_text`, `question_transcript`, `question_explain`, `question_type_id`, `part_id`, `test_id`, `group_question_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1000, 1, '{\"asset_id\":\"7d93178fd09b333ce8679b1849b5fd3b\",\"public_id\":\"toeic/2020/test1/question_audio/1\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/1.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/1.mp3\",\"duration\":21.472653}', '{\"asset_id\":\"d3743360d3fa18a89ae197bfd71f472e\",\"public_id\":\"toeic/2020/test1/question_image/1\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/1.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/1.webp\"}', NULL, '<p>(A) A woman is painting a house.</p><p>(B) A woman is watering a plant.</p><p>(C) A woman is fixing a door.</p><p>(D) A woman is sweeping a walkway.</p>', '<p>(A) Một người phụ nữ đang sơn ngôi nhà.</p><p>(B) Một người phụ nữ đang tưới cây.</p><p>(C) Một người phụ nữ đang sửa một cánh cửa.</p><p>(D) Một người phụ nữ đang quét một lối đi.</p>', 1000, '1b338528c6012352', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1001, 2, '{\"asset_id\":\"78076f4500a7b82f5c90be5fa9151a65\",\"public_id\":\"toeic/2020/test1/question_audio/2\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/2.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/2.mp3\",\"duration\":19.983673}', '{\"asset_id\":\"0c5b2652841d866bf94f590a24607936\",\"public_id\":\"toeic/2020/test1/question_image/2\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/2.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/2.webp\"}', NULL, '<p>(A) They\'re folding some papers.</p><p>(B) They\'re putting a picture in a frame.</p><p>(C) They\'re studying a drawing.</p><p>(D) They\'re closing a window.</p>', '<p>A) Họ đang gấp một số giấy tờ.</p><p>(B) Họ đang đặt một bức tranh vào khung.</p><p>(C) Họ đang nghiên cứu một bản vẽ.</p><p>(D) Họ đang đóng cửa sổ.</p>', 1000, '1b338528c6012352', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1002, 3, '{\"asset_id\":\"1dd89e8c2071037fe04e39a1adcc5d66\",\"public_id\":\"toeic/2020/test1/question_audio/3\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/3.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/3.mp3\",\"duration\":21.446531}', '{\"asset_id\":\"a9b945ee8a1cf636268d2d2fcf2cf5d1\",\"public_id\":\"toeic/2020/test1/question_image/3\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/3.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/3.webp\"}', NULL, '<p>(A) The man is turning on a light.</p><p>(B) The man is giving the woman a book.</p><p>(C) The woman is posting signs on a wall.</p><p>(D) The woman is typing on a keyboard.</p>', '<p>(A) Người đàn ông đang bật đèn.</p><p>(B) Người đàn ông đang đưa cho người phụ nữ một cuốn sách.</p><p>(C) Người phụ nữ đang dán những tấm biển trên tường.</p><p>(D) Người phụ nữ đang gõ bàn phím.</p>', 1000, '1b338528c6012352', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1003, 4, '{\"asset_id\":\"1b0409a3af4a47ed6186b9f5344178c8\",\"public_id\":\"toeic/2020/test1/question_audio/4\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/4.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/4.mp3\",\"duration\":22.073469}', '{\"asset_id\":\"cca5f789a8f63cfc8adcce9c482ee356\",\"public_id\":\"toeic/2020/test1/question_image/4\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/4.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/4.webp\"}', NULL, '<p>(A) Some clothing has been hung up.</p><p>(B) Some boxes are stacked on a cart.</p><p>(C) A bag has fallen on the floor.</p><p>(D) A chair has been pushed under a desk.</p>', '<p>(A) Quần áo đã được treo lên.</p><p>(B) Một số hộp được xếp chồng lên nhau trên một xe đẩy.</p><p>(C) Một chiếc túi bị rơi trên sàn.</p><p>(D) Một chiếc ghế đã được đẩy vào gầm bàn.</p>', 1000, '1b338528c6012352', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1004, 5, '{\"asset_id\":\"e4d5ccbf898e3597ca9b2bbd7a8db722\",\"public_id\":\"toeic/2020/test1/question_audio/5\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186909/toeic/2020/test1/question_audio/5.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186909/toeic/2020/test1/question_audio/5.mp3\",\"duration\":23.980408}', '{\"asset_id\":\"3329b711c3304b4130592ecfd0b14b41\",\"public_id\":\"toeic/2020/test1/question_image/5\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186907/toeic/2020/test1/question_image/5.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186907/toeic/2020/test1/question_image/5.webp\"}', NULL, '<p>(A) Some customers are paying for their meals.</p><p>(B) Some workers are washing dishes.</p><p>(C) Some food is being placed in a refrigerator.</p><p>(D) Some large cooking pots are on a counter.</p>', '<p>(A) Một số khách hàng đang trả tiền cho bữa ăn của họ.</p><p>(B) Một số công nhân đang rửa bát.</p><p>(C) Một số thực phẩm đang được đặt trong tủ lạnh.</p><p>(D) Một số nồi nấu ăn lớn đặt trên quầy</p>', 1000, '1b338528c6012352', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1005, 6, '{\"asset_id\":\"d70932aa807e6cf9b8c13ff610f030d3\",\"public_id\":\"toeic/2020/test1/question_audio/6\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/6.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/6.mp3\",\"duration\":24.241633}', '{\"asset_id\":\"6903d42389973fdf432e80773d844be4\",\"public_id\":\"toeic/2020/test1/question_image/6\",\"format\":\"webp\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/6.webp\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1721186906/toeic/2020/test1/question_image/6.webp\"}', NULL, '<p>(A) Runners are lined up for the start of a race.</p><p>(B) Some people are cheering for a sports team.</p><p>(C) An athletic field is located near some trees.</p><p>(D) Lawn mowers are being used to cut the grass.</p>', '<p>(A) Người chạy bộ xếp hàng để bắt đầu cuộc đua.</p><p>(B) Một số người đang cổ vũ cho một đội thể thao.</p><p>(C) Một sân thể thao nằm gần một vài cái cây.</p><p>(D) Máy cắt cỏ đang được sử dụng để cắt cỏ.</p>', 1000, '1b338528c6012352', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1006, 7, '{\"asset_id\":\"c85b080893af9384080f2e6868ac6278\",\"public_id\":\"toeic/2020/test1/question_audio/7\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/7.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/7.mp3\",\"duration\":16.300408}', NULL, NULL, '<p>Who wants to organize the patient files?</p><p>(A) Min-Su would like to.</p><p>(B) Our phone number has changed.</p><p>(C) A well-run organization.</p>', '<p>7. Ai muốn sắp xếp các tệp bệnh nhân?</p><p>(A) Min-Su muốn làm việc đó.</p><p>(B) Số điện thoại của chúng tôi đã thay đổi.</p><p>(C) Một tổ chức hoạt động có quy củ.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1007, 8, '{\"asset_id\":\"c1940f486c37c24234aee965a61e785f\",\"public_id\":\"toeic/2020/test1/question_audio/8\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/8.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/8.mp3\",\"duration\":16.065306}', NULL, NULL, '<p>Why didn\'t Miranda shut down the computers yesterday?</p><p>(A) Yes, my new laptop.</p><p>(B) Outside of office 101.</p><p>(C) Because she left early.</p>', '<p>Tại sao Miranda không tắt máy tính ngày hôm qua?</p><p>(A) Vâng, máy tính xách tay mới của tôi.</p><p>(B) Bên ngoài văn phòng 101.</p><p>(C) Bởi vì cô ấy rời đi sớm.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1008, 9, '{\"asset_id\":\"9a7bb9dea7b9e09ebef22206509d2644\",\"public_id\":\"toeic/2020/test1/question_audio/9\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/9.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/9.mp3\",\"duration\":16.065306}', NULL, NULL, '<p>Would you like the pie or the pudding for dessert?</p><p>(A) About five dollars.</p><p>(B) The pie sounds delicious.</p><p>(C) I just put it on.</p>', '<p>Ông thích bánh ngọt hay bánh pudding để tráng miệng?</p><p>(A) Khoảng năm đô la.</p><p>(B) Chiếc bánh có vẻ rất ngon.</p><p>(C) Tôi chỉ mặc nó vào.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1009, 10, '{\"asset_id\":\"183ef989bc8fd6d814b9d6360f4afb2e\",\"public_id\":\"toeic/2020/test1/question_audio/10\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/10.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/10.mp3\",\"duration\":14.837551}', NULL, NULL, '<p>Didn\'t you read Mr. Kim\'s memo?</p><p>(A) He used to live there.</p><p>(B) A newspaper article.</p><p>(C) Yes, I read it this morning.</p>', '<p>Bạn đọc thông báo của ông Kim chưa?</p><p>(A) Anh ấy đã từng sống ở đó.</p><p>(B) Một bài báo.</p><p>(C) Rồi, tôi đã đọc nó sáng nay.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1010, 11, '{\"asset_id\":\"194c97c182b0f63bd0475dc67163e934\",\"public_id\":\"toeic/2020/test1/question_audio/11\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/11.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/11.mp3\",\"duration\":17.031837}', NULL, NULL, '<p>We can put a seafood dish on the menu, can\'t we?</p><p>(A) They\'re in a stack over there.</p><p>(B) A restaurant with a view of the ocean.</p><p>(C) We can if you\'d like.</p>', '<p>Chúng ta có thể đưa một món hải sản vào thực đơn, phải không?</p><p>(A) Chúng ở trong một đống ở đằng kia.</p><p>(B) Một nhà hàng với tầm nhìn ra biển.</p><p>(C) Chúng ta có thể nếu bạn muốn.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1011, 12, '{\"asset_id\":\"92747b1f0655a9336eb115b86f65ed3c\",\"public_id\":\"toeic/2020/test1/question_audio/12\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186910/toeic/2020/test1/question_audio/12.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186910/toeic/2020/test1/question_audio/12.mp3\",\"duration\":15.516735}', NULL, NULL, '<p>Who managed the flower store last year?</p><p>(A) No, a monthly order.</p><p>(B) Some yellow roses, please.</p><p>(C) Marta did it.</p>', '<p>Ai đã quản lý cửa hàng hoa vào năm ngoái?</p><p>(A) Không, đơn đặt hàng hàng tháng.</p><p>(B) Làm ơn cho vài bông hồng vàng.</p><p>(C) Marta đã làm.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1012, 13, '{\"asset_id\":\"bf8e81d4962e8fab9763165121d3d26b\",\"public_id\":\"toeic/2020/test1/question_audio/13\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/13.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/13.mp3\",\"duration\":17.502041}', NULL, NULL, '<p>Do you mind filling out our customer-satisfaction survey?</p><p>(A) I filled the tank in the car yesterday.</p><p>(B) Sure, I can do that.</p><p>(C) The stairs are around the corner.</p>', '<p>Bạn có phiền khi điền vào bản khảo sát sự hài lòng của khách hàng của chúng tôi không? </p><p>(A) Hôm qua tôi đã đổ đầy bình trong xe.</p><p>(B) Chắc chắn, tôi có thể làm điều đó.</p><p>(C) Cầu thang ở quanh góc.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1013, 14, '{\"asset_id\":\"c411cca7b0855dc35f257bc114ad59b9\",\"public_id\":\"toeic/2020/test1/question_audio/14\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/14.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/14.mp3\",\"duration\":18.076735}', NULL, NULL, '<p>Why aren\'t those workers wearing their uniforms?</p><p>(A) Because they just finished their shift.</p><p>(B) I did work in manufacturing.</p><p>(C) A green shirt and jacket.</p>', '<p>Tại sao những công nhân đó không mặc đồng phục của họ?</p><p>(A) Vì họ vừa kết thúc ca làm việc.</p><p>(B) Tôi đã làm việc trong lĩnh vực sản xuất.</p><p>(C) Một chiếc áo sơ mi và áo khoác màu xanh lá cây.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1014, 15, '{\"asset_id\":\"6447c7ebfbfe873e1a56d84904a1bf45\",\"public_id\":\"toeic/2020/test1/question_audio/15\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/15.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/15.mp3\",\"duration\":16.404898}', NULL, NULL, '<p>Do you want me to ask Jake about the report?</p><p>(A) Yes, that\'s a good idea.</p><p>(B) Somewhere on your desk.</p><p>(C) How was the conference?</p>', '<p>Bạn có muốn tôi hỏi Jake về bản báo cáo không?</p><p>(A) Vâng, đó là một ý kiến hay.</p><p>(B) Ở đâu đó trên bàn làm việc của bạn.</p><p>(C) Hội nghị thế nào?</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1015, 16, '{\"asset_id\":\"c5acc225e809596dd82b3c4eb09a7c55\",\"public_id\":\"toeic/2020/test1/question_audio/16\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/16.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/16.mp3\",\"duration\":17.81551}', NULL, NULL, '<p>Should I display the data on a chart or on a graph?</p><p>(A) They\'re more energy efficient.</p><p>(B) No, that can\'t be right.</p><p>(C) A graph would be better.</p>', '<p>Tôi nên trình bày dữ liệu trên biểu đồ hay trên đồ thị?</p><p>(A) Chúng tiết kiệm năng lượng hơn.</p><p>(B) Không, điều đó không thể đúng.</p><p>(C) Đồ thị sẽ tốt hơn.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1016, 17, '{\"asset_id\":\"7987cc26fc6c56ad65e9a74f404abf8d\",\"public_id\":\"toeic/2020/test1/question_audio/17\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/17.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/17.mp3\",\"duration\":15.020408}', NULL, NULL, '<p>Where can I get breakfast near this hotel?</p><p>(A) Cream and sugar please.</p><p>(B) Well, you have a few options.</p><p>(C) I believe so.</p>', '<p>Tôi có thể ăn sáng ở đâu gần khách sạn này?</p><p>&nbsp;(A) Kem và đường.</p><p>(B) Chà, bạn có một vài lựa chọn.</p><p>(C) Tôi tin như vậy.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1017, 18, '{\"asset_id\":\"edaa06950615500d2b5dd26a0eeda918\",\"public_id\":\"toeic/2020/test1/question_audio/18\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/18.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/18.mp3\",\"duration\":16.248163}', NULL, NULL, '<p>What was our net profit for the second quarter?</p><p>(A) No, he arrived first.</p><p>(B) At the new tennis club.</p><p>(C) Ten thousand dollars.</p>', '<p>Lợi nhuận ròng của chúng ta trong quý thứ hai là bao nhiêu?</p><p>(A) Không, anh ấy đến trước.</p><p>(B) Tại câu lạc bộ quần vợt mới.</p><p>(C) Mười nghìn đô la.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1018, 19, '{\"asset_id\":\"6563c146f2bf9669dcde1abbd56715f6\",\"public_id\":\"toeic/2020/test1/question_audio/19\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/19.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/19.mp3\",\"duration\":16.692245}', NULL, NULL, '<p>Why don\'t you check the prices at a different paint store?</p><p>(A) Is there one that you suggest?</p><p>(B) Check-in is at eleven o\'clock.</p><p>(C) No, she\'s a photographer.</p>', '<p>Tại sao bạn không kiểm tra giá ở một cửa hàng sơn khác?</p><p>&nbsp;(A) Bạn có gợi ý cái nào không?</p><p>(B) Nhận phòng lúc mười một giờ.</p><p>(C) Không, cô ấy là một nhiếp ảnh gia.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1019, 20, '{\"asset_id\":\"54f1b4f07cce13e2be06e8ad9d180899\",\"public_id\":\"toeic/2020/test1/question_audio/20\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/20.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/20.mp3\",\"duration\":15.830204}', NULL, NULL, '<p>When will the presentation begin?</p><p>(A) Actually, I\'m not presenting today.</p><p>(B) The production numbers.</p><p>(C) A screen and a projector.</p>', '<p>Khi nào bài thuyết trình sẽ bắt đầu?</p><p>(A) Thực ra, hôm nay tôi không thuyết trình.</p><p>(B) Số lượng sản xuất.</p><p>(C) Một màn hình và một máy chiếu.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1020, 21, '{\"asset_id\":\"c937e91e18fff58c8a058c95aef584a1\",\"public_id\":\"toeic/2020/test1/question_audio/21\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/21.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/21.mp3\",\"duration\":16.64}', NULL, NULL, '<p>We\'re trying to cut our delivery times.</p><p>(A) The cords are too long.</p><p>(B) Our customers will appreciate that.</p><p>(C) The boxes in the closet.</p>', '<p>Chúng tôi đang cố gắng cắt giảm thời gian giao hàng.</p><p>(A) Dây quá dài.</p><p>(B) Khách hàng của chúng tôi sẽ đánh giá cao điều đó.</p><p>(C) Các hộp trong tủ quần áo.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1021, 22, '{\"asset_id\":\"c705aba3a4f780dfbe362ca74cd5c963\",\"public_id\":\"toeic/2020/test1/question_audio/22\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/22.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/22.mp3\",\"duration\":18.573061}', NULL, NULL, '<p>How much juice should I buy for the staff meeting?</p><p>(A) Sure, I\'ll take the receipt to accounting.</p><p>(B) Everyone from the departments attending.</p><p>(C) Do you want to get some lunch now?</p>', '<p>Tôi nên mua bao nhiêu nước trái cây cho cuộc họp nhân viên?</p><p>(A) Chắc chắn, tôi sẽ mang biên lai cho kế toán.</p><p>(B) Mọi người từ bộ phận đều tham dự.</p><p>(C) Bây giờ bạn có muốn đi ăn trưa không?</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1022, 23, '{\"asset_id\":\"d30a682b95ef5b05158bf684ac9c8406\",\"public_id\":\"toeic/2020/test1/question_audio/23\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/23.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/23.mp3\",\"duration\":16.43102}', NULL, NULL, '<p>Shouldn\'t you have left for your trip already?</p><p>(A) A couple of suitcases.</p><p>(B) The flight was delayed.</p><p>(C) Actually, it\'s on the right.</p>', '<p>Bạn không nên xuất phát cho chuyến đi của mình rồi sao?</p><p>(A) Một vài chiếc vali.</p><p>(B) Chuyến bay bị hoãn.</p><p>(C) Thực ra nó ở bên phải.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1023, 24, '{\"asset_id\":\"4be602bc6b6c8e21349ac51f83d9c24a\",\"public_id\":\"toeic/2020/test1/question_audio/24\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/24.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/24.mp3\",\"duration\":18.468571}', NULL, NULL, '<p>Has the warranty expired for our solar-powered lights?</p><p>(A) No, we still have two more months.</p><p>(B) On the wall beneath the whiteboard.</p><p>(C) The session starts at ten A.M.</p>', '<p>Đèn năng lượng mặt trời của chúng tôi đã hết hạn bảo hành chưa?</p><p>(A) Chưa, chúng ta vẫn còn hai tháng nữa.</p><p>(B) Trên bức tường bên dưới bảng trắng.</p><p>(C) Phiên họp bắt đầu lúc 10 giờ sáng</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1024, 25, '{\"asset_id\":\"50885fc3ce27fd171a36490c4de7624a\",\"public_id\":\"toeic/2020/test1/question_audio/25\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/25.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/25.mp3\",\"duration\":16.561633}', NULL, NULL, '<p>You\'ve placed the supply order, haven\'t you?</p><p>(A) On the desk is fine.</p><p>(B) It was a surprise party.</p><p>(C) I just submitted the payment.</p>', '<p>Bạn đã đặt hàng cung ứng, phải không?</p><p>(A) Trên bàn làm việc là được.</p><p>(B) Đó là một bữa tiệc bất ngờ.</p><p>(C) Tôi vừa gửi khoản thanh toán.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1025, 26, '{\"asset_id\":\"f9219a957394d7bae037eb82c0ee1a9b\",\"public_id\":\"toeic/2020/test1/question_audio/26\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/26.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/26.mp3\",\"duration\":17.345306}', NULL, NULL, '<p>When are you showing your clients the house on Bell Street?</p><p>(A) On the third floor.</p><p>(B) Tomorrow afternoon.</p><p>(C) It\'s playing at the downtown theater.</p>', '<p>Khi nào bạn cho khách hàng xem ngôi nhà trên Phố Bell?</p><p>(A) Trên tầng ba.</p><p>(B) Chiều mai.</p><p>(C) Nó đang chiếu ở nhà hát trung tâm thành phố.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1026, 27, '{\"asset_id\":\"23e449b368790c0219a1e5614de52a5d\",\"public_id\":\"toeic/2020/test1/question_audio/27\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/27.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/27.mp3\",\"duration\":16.169796}', NULL, NULL, '<p>How long will the building addition take to complete?</p><p>(A) I\'m reviewing the plans now.</p><p>(B) You can take that.</p><p>(C) In the back of the truck.</p>', '<p>Việc xây dựng thêm tòa nhà sẽ mất bao lâu để hoàn thành?</p><p>(A) Bây giờ tôi đang xem xét các kế hoạch.</p><p>(B) Bạn có thể lấy điều đó.</p><p>(C) Ở phía sau xe tải</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1027, 28, '{\"asset_id\":\"80f0ab69155fa9919d135470b9997811\",\"public_id\":\"toeic/2020/test1/question_audio/28\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/28.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/28.mp3\",\"duration\":17.136327}', NULL, NULL, '<p>Which envelope should I use to mail these photos?</p><p>(A) No, I\'m not using it.</p><p>(B) By the post office.</p><p>(C) Are you sending them express?</p>', '<p>Tôi nên sử dụng phong bì nào để gửi những bức ảnh này?</p><p>(A) Không, tôi không sử dụng nó.</p><p>(B) Qua bưu điện.</p><p>(C) Bạn có đang gửi chúng qua dịch vụ chuyển phát nhanh không?</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1028, 29, '{\"asset_id\":\"1af55e2b3a30895463fecd0ce18fba23\",\"public_id\":\"toeic/2020/test1/question_audio/29\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/29.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186907/toeic/2020/test1/question_audio/29.mp3\",\"duration\":16.378776}', NULL, NULL, '<p>The quality-control team is inspecting the factory soon.</p><p>(A) Some spare parts.</p><p>(B) Thanks, it went well.</p><p>(C) Everything is ready.</p>', '<p>Đội kiểm tra chất lượng sẽ sớm kiểm tra nhà máy.</p><p>(A) Một số phụ tùng thay thế.</p><p>(B) Cảm ơn, mọi việc diễn ra tốt đẹp.</p><p>(C) Mọi thứ đã sẵn sàng.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1029, 30, '{\"asset_id\":\"4cd25d4d4279844374443d07d5699ad4\",\"public_id\":\"toeic/2020/test1/question_audio/30\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/30.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186908/toeic/2020/test1/question_audio/30.mp3\",\"duration\":14.445714}', NULL, NULL, '<p>Where\'s the nearest bus stop?</p><p>(A) They work closely together.</p><p>(B) He left it at home.</p><p>(C) I\'m going there now.</p>', '<p>Bến xe buýt gần nhất ở đâu?</p><p>(A) Chúng phối hợp chặt chẽ với nhau.</p><p>(B) Anh ấy để nó ở nhà.</p><p>(C) Tôi sẽ đến đó ngay bây giờ.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1030, 31, '{\"asset_id\":\"d3d88f2bdae997bf450c0dcd5ab7b39a\",\"public_id\":\"toeic/2020/test1/question_audio/31\",\"format\":\"mp3\",\"resource_type\":\"video\",\"url\":\"http://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/31.mp3\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/video/upload/v1721186906/toeic/2020/test1/question_audio/31.mp3\",\"duration\":17.789388}', NULL, NULL, '<p>Could I come to your office today to sign the rental contract?</p><p>(A) A one-bedroom apartment.</p><p>(B) I\'ll be here until five o\'clock.</p><p>(C) Two thousand dollars a month.</p>', '<p>Hôm nay tôi có thể đến văn phòng của bạn để ký hợp đồng thuê nhà được không?</p><p>(A) Căn hộ một phòng ngủ.</p><p>(B) Tôi sẽ ở đây cho đến năm giờ.</p><p>(C) Hai nghìn đô la một tháng.</p>', 1001, '3ce12c00bb4cf089', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1031, 32, NULL, NULL, 'Where is the conversation most likely taking place?', NULL, '<p>Cuộc hội thoại có khả năng diễn ra ở đâu nhất?</p><p>(A) Tại một cửa hàng đồ kim khí</p><p>(B) Tại một cửa hàng quần áo</p><p>(C) Tại một tiệm bánh</p><p>(D) Tại một hiệu thuốc</p>', 1002, '45ec88f1298a1d01', 1000, 1, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1032, 33, NULL, NULL, 'How do the speakers hope to increase sales?', NULL, '<p>Làm thế nào để người nói hy vọng sẽ tăng doanh số bán hàng?</p><p>(A) Bằng cách quảng cáo trực tuyến</p><p>(B) Bằng cách cung cấp một sản phẩm mới</p><p>(C) Bằng cách cung cấp dịch vụ giao hàng miễn phí</p><p>(D) Bằng cách giảm giá một số mặt hàng</p>', 1002, '45ec88f1298a1d01', 1000, 1, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1033, 34, NULL, NULL, 'What will the man do next?', NULL, '<p>Người đàn ông sẽ làm gì tiếp theo?</p><p>&nbsp;(A) Liên hệ với nhà cung cấp</p><p>(B) Nói chuyện với đồng nghiệp</p><p>(C) Nộp một số hóa đơn</p><p>(D) Nhận thêm một số phụ gia</p>', 1002, '45ec88f1298a1d01', 1000, 1, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1034, 35, NULL, NULL, 'What does the woman say a town recently did?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ nói một thị trấn gần đây đã làm gì?</p><p>(A) Nó đã bầu một thị trưởng.</p><p>(B) Nó đã cố định một đường tàu.</p><p>(C) Nó đã làm sạch một công viên cộng đồng.</p><p>(D) Nó đã thêm một làn đường dành cho xe đạp.</p>', 1002, '45ec88f1298a1d01', 1000, 2, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1035, 36, NULL, NULL, 'Why is the woman pleased about a change?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người phụ nữ hài lòng về một sự thay đổi?</p><p>(A) Hóa đơn hàng tháng của cô ấy thấp hơn.</p><p>(B) Cô ấy đi làm nhanh hơn.</p><p>(C) Tái chế dễ dàng hơn.</p><p>(D) Một khu phố trông đẹp hơn.</p>', 1002, '45ec88f1298a1d01', 1000, 2, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1036, 37, NULL, NULL, 'What does the man suggest the woman do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông đề nghị người phụ nữ làm gì?</p><p>(A) Tham gia câu lạc bộ</p><p>(B ) Tham gia cuộc thi</p><p>(C) Kiểm tra chương trình làm việc</p><p>(D) Đăng đánh giá</p>', 1002, '45ec88f1298a1d01', 1000, 2, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1037, 38, NULL, NULL, 'What type of company do the men work for?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Loại công ty mà nam giới làm việc?</p><p>(A) Một công ty kiến trúc</p><p>(B) Một công ty kỹ thuật</p><p>(C) Một công ty xây dựng</p><p>(D) Một nhà sản xuất thiết bị điện tử</p>', 1002, '45ec88f1298a1d01', 1000, 3, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1038, 39, NULL, NULL, 'What is the purpose of the telephone call?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Mục đích của cuộc gọi điện thoại là gì?</p><p>(A) Để hủy đơn đặt hàng</p><p>(B) Để sắp xếp một cuộc phỏng vấn</p><p>(C) Để hỏi về một chính sách</p><p>(D) Để xác nhận một đặt phòng</p>', 1002, '45ec88f1298a1d01', 1000, 3, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1039, 40, NULL, NULL, 'What will be sent to the woman?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Những gì sẽ được gửi cho người phụ nữ?</p><p>(A) Một bài báo trên tạp chí</p><p>(B) Một bảo hành</p><p>(C) Chỉ đường đến một địa điểm</p><p>(D) Hướng dẫn hoàn lại tiền</p>', 1002, '45ec88f1298a1d01', 1000, 3, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1040, 41, NULL, NULL, 'Where does the man work?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông làm việc ở đâu?</p><p>(A) Tại một bến xe</p><p>(B) Tại một công ty tài chính</p><p>(C) Tại văn phòng nha khoa</p><p>(D) Tại một cửa hàng sửa chữa ô tô</p>', 1002, '45ec88f1298a1d01', 1000, 4, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1041, 42, NULL, NULL, 'What does the man offer to contact the woman about?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông đề nghị liên hệ với người phụ nữ về điều gì?</p><p>(A) Giờ nghỉ của doanh nghiệp</p><p>(B) Bắt đầu cuộc hẹn</p><p>(C) Tình trạng giao hàng</p><p>(D) Chi phí dịch vụ</p>', 1002, '45ec88f1298a1d01', 1000, 4, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1042, 43, NULL, NULL, 'Why does the man say, \"the Number 10 bus stops right outside our building\"?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người đàn ông nói, \"Xe buýt số 10 dừng ngay bên ngoài tòa nhà của chúng tôi\"?</p><p>(A) Khuyên người phụ nữ đi xe buýt</p><p>(B) Yêu cầu mở rộng tuyến xe buýt</p><p>(C) Sửa lỗi trên bản đồ</p><p>(D) Khiếu nại về tiếng ồn giao thông</p>', 1002, '45ec88f1298a1d01', 1000, 4, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1043, 44, NULL, NULL, 'Where are the speakers?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói ở đâu?</p><p>(A) Tại cửa hàng bách hóa</p><p>(B) Tại phòng khám y tế</p><p>(C) Tại thư viện</p><p>(D) Tại ngân hàng</p>', 1002, '45ec88f1298a1d01', 1000, 5, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1044, 45, NULL, NULL, 'What is the woman trying to do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ đang cố gắng làm gì?</p><p>(A) Lấy đơn thuốc</p><p>(B) Tham gia chương trình tặng thưởng</p><p>(C) Gửi tiền</p><p>(D) Mượn sách</p>', 1002, '45ec88f1298a1d01', 1000, 5, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1045, 46, NULL, NULL, 'What will the man do next?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông sẽ làm gì tiếp theo?</p><p>(A) Nói chuyện với người quản lý</p><p>(B) Chuẩn bị một số biểu mẫu</p><p>(C) Hoàn lại tiền khi mua hàng</p><p>(D) Nâng cấp một số phần mềm</p>', 1002, '45ec88f1298a1d01', 1000, 5, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1046, 47, NULL, NULL, 'What product are the distributors coming to see?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Nhà phân phối đến xem sản phẩm gì?</p><p>(A) Một chiếc xe</p><p>(B) Một điện thoại di động</p><p>(C) Một bàn máy tính</p><p>(D) Một tủ lạnh</p>', 1002, '45ec88f1298a1d01', 1000, 6, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1047, 48, NULL, NULL, 'Why has the meeting been rescheduled?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao cuộc họp đã được lên lịch lại?</p><p>(A) Một số tài liệu không đến nơi.</p><p>(B) Một số nhân viên vẫn đang đào tạo.</p><p>(C) Một chuyến bay bị hoãn.</p><p>(D) Một phòng không có sẵn.</p>', 1002, '45ec88f1298a1d01', 1000, 6, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1048, 49, NULL, NULL, 'What will the woman do next?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ sẽ làm gì tiếp theo?</p><p>(A) Gọi dịch vụ xe hơi</p><p>(B) Nộp một số thủ tục giấy tờ</p><p>(C) Thuê một số người phục vụ ăn uống</p><p>(D) Kiểm tra một số thiết bị</p>', 1002, '45ec88f1298a1d01', 1000, 6, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1049, 50, NULL, NULL, 'Where are the speakers?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói ở đâu?</p><p>(A) Tại một hội nghị</p><p>(B) Tại một chuyến tham quan nhà máy</p><p>(C) Tại một cuộc phỏng vấn</p><p>(D) Tại một phòng thí nghiệm</p>', 1002, '45ec88f1298a1d01', 1000, 7, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1050, 51, NULL, NULL, 'What does the man say he wants to do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông nói anh ta muốn làm gì?</p><p>(A) Chụp một số hình ảnh</p><p>(B) Đặt câu hỏi</p><p>(C) Xem xét một số máy móc</p><p>(D) Xem lại slide trình chiếu</p>', 1002, '45ec88f1298a1d01', 1000, 7, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1051, 52, NULL, NULL, 'What does the woman remind the man to do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ nhắc nhở người đàn ông làm gì?</p><p>(A) Gửi sơ yếu lý lịch</p><p>&nbsp;(B) Trả phí</p><p>(C) Chọn một mục</p><p>(D) Thưởng thức đồ uống giải khát</p>', 1002, '45ec88f1298a1d01', 1000, 7, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1052, 53, NULL, NULL, 'What business is the man calling from?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông đang gọi đến từ doanh nghiệp nào?</p><p>(A) Một công ty kiến trúc</p><p>(B) Một đại lý tiếp thị</p><p>(C) Một cửa hàng điện tử</p><p>(D) Một cửa hàng in ấn</p>', 1002, '45ec88f1298a1d01', 1000, 8, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1053, 54, NULL, NULL, 'Why does the woman say, \"We actually have a new company logo”?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người phụ nữ nói, \"Chúng tôi thực sự có một logo công ty mới\"?</p><p>(A) Để khen ngợi đồng nghiệp</p><p>&nbsp;(B) Để trấn an khách hàng</p><p>&nbsp;(C) Yêu cầu cập nhật đơn đặt hàng</p><p>&nbsp;(D) Để bày tỏ sự ngạc nhiên trước một quyết định</p>', 1002, '45ec88f1298a1d01', 1000, 8, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1054, 55, NULL, NULL, 'What does the woman ask the man to do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ yêu cầu người đàn ông làm gì?</p><p>(A) Tính phí thẻ tín dụng</p><p>(B) Nhận được sự chấp thuận của người giám sát</p><p>(C) Đóng tài khoản</p><p>(D) Cập nhật hợp đồng</p>', 1002, '45ec88f1298a1d01', 1000, 8, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1055, 56, NULL, NULL, 'What do the women do at the museum?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Những người phụ nữ làm gì ở bảo tàng?</p><p>(A) Quản lý cửa hàng quà tặng</p><p>(B) Dẫn dắt các chuyến tham quan</p><p>(C) Thu thập các khoản đóng góp</p><p>(D) Khôi phục các bức tranh</p>', 1002, '45ec88f1298a1d01', 1000, 9, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1056, 57, NULL, NULL, 'What most likely caused an increase in museum visitors?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Điều gì có khả năng làm tăng lượng khách tham quan bảo tàng?</p><p>(A) Bãi đậu xe miễn phí</p><p>(B) Giờ hoạt động kéo dài</p><p>(C) Một cuộc triển lãm mới</p><p>(D) Giá vé thấp hơn</p>', 1002, '45ec88f1298a1d01', 1000, 9, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1057, 58, NULL, NULL, 'According to the man, what will happen on Thursday?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Theo người đàn ông, điều gì sẽ xảy ra vào thứ Năm?</p><p>(A) Một bộ phim sẽ được chiếu.</p><p>(B) Một bài báo sẽ được xuất bản.</p><p>(C) Một quan chức thành phố sẽ tổ chức một buổi gây quỹ.</p><p>(D) Một nhà sưu tập nghệ thuật sẽ thuyết trình.</p>', 1002, '45ec88f1298a1d01', 1000, 9, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1058, 59, NULL, NULL, 'What problem does the man have?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông có vấn đề gì?</p><p>(A) Anh ấy đã bị tính phí quá cao cho một dịch vụ.</p><p>(B) Anh ấy quên mật khẩu của mình.</p><p>(C) Máy tính của anh ấy chưa được giao.</p><p>(D) Máy tính của anh ấy không hoạt động bình thường.</p>', 1002, '45ec88f1298a1d01', 1000, 10, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1059, 60, NULL, NULL, 'What did the man\'s purchase include?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông đã mua những thứ gì?</p><p>(A) Bảo vệ màn hình</p><p>(B) Hộp đựng</p><p>(C) Hỗ trợ kỹ thuật</p><p>(D) Bảo vệ chống vi-rút</p>', 1002, '45ec88f1298a1d01', 1000, 10, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1060, 61, NULL, NULL, 'What information does the woman request?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ yêu cầu thông tin gì?</p><p>(A) Số điện thoại</p><p>(B) Địa chỉ gửi thư</p><p>(C) Số kiểu máy</p><p>(D) Ngày mua</p>', 1002, '45ec88f1298a1d01', 1000, 10, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1061, 62, NULL, NULL, 'What are the speakers preparing for?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói đang chuẩn bị cho cái gì?</p><p>(A) Một hội chợ việc làm</p><p>(B) Một chuyến thăm khách hàng</p><p>(C) Một buổi đào tạo</p><p>(D) Một bữa tối nghỉ hưu</p>', 1002, '45ec88f1298a1d01', 1000, 11, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1062, 63, NULL, NULL, 'Look at the graphic. How much will the speakers most likely spend per person?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Nhìn vào hình ảnh. Những người nói khả năng sẽ chi bao nhiêu tiền cho mỗi người?</p><p>(A) $ 6</p><p>(B) $ 8</p><p>(C) $ 10</p><p>(D) $ 12</p>', 1002, '45ec88f1298a1d01', 1000, 11, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1063, 64, NULL, NULL, 'What does the woman say she will do next?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ nói cô ấy sẽ làm gì tiếp theo?</p><p>(A) Chuẩn bị hành trình</p><p>(B) Mua vé tàu</p><p>(C) Ghé thăm một số nhà hàng</p><p>(D) Xác nhận đặt phòng khách sạn</p>', 1002, '45ec88f1298a1d01', 1000, 11, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1064, 65, NULL, NULL, 'Why does the woman want to talk to the man?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người phụ nữ muốn nói chuyện với người đàn ông?</p><p>A) Để xin một số lời khuyên</p><p>B) Để thảo luận về một khiếu nại</p><p>(C) Để giải thích sự thay đổi lịch trình</p><p>(D) Để từ chối lời mời</p>', 1002, '45ec88f1298a1d01', 1000, 12, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1065, 66, NULL, NULL, 'Look at the graphic. Which step in the procedure does the woman mention?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Nhìn vào tranh. Người phụ nữ đề cập đến bước nào trong quy trình?</p><p>(A) Bước 1</p><p>(B) Bước 2</p><p>(C) Bước 3</p><p>(D) Bước 4</p>', 1002, '45ec88f1298a1d01', 1000, 12, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1066, 67, NULL, NULL, 'What does the woman say she will do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người phụ nữ nói rằng cô ấy sẽ làm gì?</p><p>(A) Đăng một số hướng dẫn</p><p>(B) Cất bớt thiết bị</p><p>(C) Viết báo cáo</p><p>(D) Chuyển tiếp&nbsp;e-mail</p>', 1002, '45ec88f1298a1d01', 1000, 12, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1067, 68, NULL, NULL, 'Where do the speakers most likely work?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Những người nói có khả năng làm việc ở đâu nhất?</p><p>(A) Tại cửa hàng kim khí</p><p>(B) Tại trường dạy lái xe</p><p>(C) Tại công ty cung cấp ô tô</p><p>(D) Tại công ty vận chuyển quốc tế</p>', 1002, '45ec88f1298a1d01', 1000, 13, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1068, 69, NULL, NULL, 'Look at the graphic. Which month\'s sales figures does the woman ask about?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Nhìn vào hình ảnh. Người phụ nữ hỏi số liệu bán hàng của tháng nào?</p><p>(A) Tháng Một</p><p>(B) Tháng Hai</p><p>(C) Tháng Ba</p><p>(D) Tháng Tư</p><p><br></p>', 1002, '45ec88f1298a1d01', 1000, 13, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1069, 70, NULL, NULL, 'What does the man say they will do this month?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người đàn ông nói họ sẽ làm gì trong tháng này?</p><p>(A) Khởi động chiến dịch tiếp thị mới</p><p>(B) Giảm giá khi mua số lượng lớn</p><p>(C) Thuê chuyên gia tư vấn</p><p>(D) Tăng sản lượng</p>', 1002, '45ec88f1298a1d01', 1000, 13, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1070, 71, NULL, NULL, 'According to the speaker, what will take place on Saturday?', NULL, '<p>Theo người nói, thứ bảy sẽ diễn ra điều gì?</p><p>(A) Một bữa tiệc hưu trí</p><p>(B) Một cuộc diễu hành trong ngày lễ</p><p>(C) Một hội thảo kinh doanh</p><p>(D) Một chuyến dã ngoại của công ty</p>', 1003, '42252db43b18e24e', 1000, 14, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1071, 72, NULL, NULL, 'Where do the listeners work?', NULL, '<p>Người nghe làm việc ở đâu?</p><p>(A) Tại ngân hàng</p><p>(B) Tại công viên giải trí</p><p>(C) Tại nhà hàng</p><p>(D) Tại đồn cảnh sát</p>', 1003, '42252db43b18e24e', 1000, 14, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1072, 73, NULL, NULL, 'What does the speaker suggest that the listeners do?', NULL, '<p>Người nói đề nghị người nghe làm gì?</p><p>(A) Mặc quần áo ấm</p><p>(B) Sử dụng phương tiện giao thông công cộng</p><p>(C) Mang theo bữa trưa</p><p>(D) Mang theo giấy tờ tùy thân</p>', 1003, '42252db43b18e24e', 1000, 14, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1073, 74, NULL, NULL, 'Where does the speaker most likely work?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói có khả năng làm việc ở đâu nhất?</p><p>(A) Tại một tổ chức quảng cáo</p><p>(B) Tại một công ty công nghệ</p><p>(C) Tại bảo tàng nghệ thuật</p><p>(D) Tại một cửa hàng điện tử</p>', 1003, '42252db43b18e24e', 1000, 15, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1074, 75, NULL, NULL, 'What is the talk mainly about?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Cuộc nói chuyện chủ yếu nói về vấn đề gì?</p><p>(A) Cập nhật biểu tượng</p><p>(B) Thay đổi bộ trình bày</p><p>(C) Tổ chức cuộc thi</p><p>(D) Tổ chức hội thảo</p><p><br></p>', 1003, '42252db43b18e24e', 1000, 15, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1075, 76, NULL, NULL, 'What does the speaker say he will do this morning?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói nói anh ấy sẽ làm gì sáng nay?</p><p>(A) Sắp xếp một cuộc họp</p><p>(B) Gởi đơn hàng</p><p>(C) Cập nhật một trang web</p><p>(D) In vài tờ quảng cáo</p>', 1003, '42252db43b18e24e', 1000, 15, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1076, 77, NULL, NULL, 'What is the speaker mainly discussing?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>người nói chủ yếu thảo luận về vấn đề gì?</p><p>(A) Một chương trình máy tính</p><p>(B) Một băng chuyền</p><p>(C) Một khoang chứa</p><p>(D) Một quạt làm mát</p>', 1003, '42252db43b18e24e', 1000, 16, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1077, 78, NULL, NULL, 'What key difference does the speaker point out?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Sự khác biệt quan trọng nào mà người nói chỉ ra?</p><p>A) Một số máy móc sẽ chạy nhanh hơn.</p><p>(B) Một số báo động nhạy hơn.</p><p>(C) Mật khẩu đã được thay đổi.</p><p>(D) Bảng thời gian hoạt động</p>', 1003, '42252db43b18e24e', 1000, 16, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1078, 79, NULL, NULL, 'What does the speaker say the listeners must do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói nói người nghe phải làm gì?</p><p>(A) Nói chuyện với người giám sát</p><p>(B) Ký tài liệu</p><p>(C) Xem video</p><p>(D) Làm thêm giờ</p>', 1003, '42252db43b18e24e', 1000, 16, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1079, 80, NULL, NULL, 'According to the speaker, what will happen on Wednesday?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Theo người nói, điều gì sẽ xảy ra vào Thứ tư?</p><p>(A) Hội chợ nghề nghiệp</p><p>(B) Chương trình giảm giá</p><p>(C) Kiểm tra địa điểm làm việc</p><p>(D) Định hướng cho nhân viên</p>', 1003, '42252db43b18e24e', 1000, 17, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1080, 81, NULL, NULL, 'What does the speaker imply when she says, \'\'I don\'t have any appointments tomorrow\"?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói ngụ ý gì khi cô ấy nói, \'\' Tôi không có cuộc hẹn nào vào ngày mai \"?</p><p>(A) Cô ấy không trao đổi thành công với khách hàng</p><p>(B) Cô ấy nghĩ thời gian biểu bị sai</p><p>(C) Cô ấy có thời gian để hoàn thiện công việc</p><p>(D) Cô ấy cần về sớm</p>', 1003, '42252db43b18e24e', 1000, 17, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1081, 82, NULL, NULL, 'What does the speaker ask the listener to do?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói yêu cầu người nghe làm gì?</p><p>(A) Gọi lại cho cô ấy</p><p>(B) Kiểm tra lịch</p><p>(C) Đặt trước một gian hàng</p><p>(D) Hủy một sự kiện</p><p><br></p>', 1003, '42252db43b18e24e', 1000, 17, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1082, 83, NULL, NULL, 'According to the speaker, what is special about this month\'s issue of Tech Now?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Theo người nói, chủ đề của Tech Now trong tháng này có gì đặc biệt?</p><p>(A) Nó miễn phí cho sinh viên các trường đại học.</p><p>(B) Nó có chủ đề về phụ nữ trong lĩnh vực công nghệ.</p><p>(C) Đây là số đầu tiên của tạp chí.</p><p>(D) Nó có một cuộc khảo sát độc giả.</p>', 1003, '42252db43b18e24e', 1000, 18, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL);
INSERT INTO `questions` (`question_id`, `question_order`, `question_audio`, `question_image`, `question_text`, `question_transcript`, `question_explain`, `question_type_id`, `part_id`, `test_id`, `group_question_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1083, 84, NULL, NULL, 'Who is Erika Cliffton?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Erika Cliffton là ai?</p><p>(A) Người sáng lập công ty</p><p>(B) Một nhà báo</p><p>(C) Một vận động viên</p><p>(D) Một nhà tư vấn tài chính</p>', 1003, '42252db43b18e24e', 1000, 18, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1084, 85, NULL, NULL, 'What does the magazine offer this week with a subscription?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tạp chí cung cấp những gì trong tuần này với người đăng ký?</p><p>(A) Một túi đựng máy tính xách tay</p><p>(B) Một chiếc ô</p><p>(C) Quyền truy cập vào danh sách việc làm</p><p>(D) Một phiếu giảm giá cho một cửa hàng</p>', 1003, '42252db43b18e24e', 1000, 18, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1085, 86, NULL, NULL, 'What is the broadcast mainly about?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Chương trình phát sóng chủ yếu là về cái gì?</p><p>(A) Lời khuyên về chế độ ăn uống</p><p>(B) Lời khuyên tập thể dục</p><p>(C) Cải thiện giấc ngủ</p><p>(D) Giảm căng thẳng</p>', 1003, '42252db43b18e24e', 1000, 19, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1086, 87, NULL, NULL, 'Why does the speaker say she is surprised?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người nói nói cô ấy ngạc nhiên?</p><p>(A) Một nhiệm vụ có thể rất tốn thời gian.</p><p>(B) Một quan điểm phổ biến không chính xác.</p><p>(C) Một doanh nghiệp địa phương đang đóng cửa.</p><p>(D) Một người nói đến muộn.</p>', 1003, '42252db43b18e24e', 1000, 19, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1087, 88, NULL, NULL, 'Why does the speaker say, \"We\'ll be talking about that on next week\'s broadcast\"?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người nói nói: \"Chúng ta sẽ nói về điều đó trong chương trình phát sóng vào tuần tới\"?</p><p>(A) Thay đổi lịch trình</p><p>(B) Khiếu nại</p><p>(C) Từ chối yêu cầu</p><p>(D) Công bố một tập trong tương lai</p>', 1003, '42252db43b18e24e', 1000, 19, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1088, 89, NULL, NULL, 'According to the speaker, what is unique about the airport?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Theo người nói, sân bay có gì độc đáo?</p><p>(A) Nó sẽ được cung cấp bởi năng lượng mặt trời.</p><p>(B) Nó sẽ được làm từ vật liệu tái chế.</p><p>(C) Nó sẽ được xây dựng bởi một kiến trúc sư nổi tiếng.</p><p>(D) Nó sẽ là lớn nhất trong cả nước</p>', 1003, '42252db43b18e24e', 1000, 20, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1089, 90, NULL, NULL, 'What does the speaker say will happen next month?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>người nói nói điều gì sẽ xảy ra vào tháng tới?</p><p>(A) Một cuộc họp hội đồng quản trị</p><p>(B) Một buổi đào tạo</p><p>C) Một hội chợ việc làm</p><p>(D) Một buổi khai trương</p><p><br></p>', 1003, '42252db43b18e24e', 1000, 20, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1090, 91, NULL, NULL, 'According to the speaker, how can the listeners get information about the construction firm?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Theo người nói, làm thế nào người nghe có thể nhận được thông tin về công ty xây dựng?</p><p>(A) Bằng cách gọi số điện thoại miễn phí</p><p>(B) Bằng cách truy cập trang web</p><p>(C) Bằng cách xem phim tài liệu</p><p>(D) Bằng cách nhận một tập quảng cáo</p><p><br></p>', 1003, '42252db43b18e24e', 1000, 20, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1091, 92, NULL, NULL, 'What is the topic of this week\'s podcast?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Chủ đề của podcast tuần này là gì?</p><p>(A) Di tích lịch sử</p><p>(B) Một số bức tranh bị mất tích</p><p>(C) Văn học cổ điển</p><p>(D) Các nhà soạn nhạc châu Âu</p>', 1003, '42252db43b18e24e', 1000, 21, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1092, 93, NULL, NULL, 'Who is the guest on this week\'s podcast?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Ai là khách mời trên podcast của tuần này?</p><p>(A) Một diễn viên</p><p>(B) Một đại lý du lịch</p><p>(C) Một chính trị gia</p><p>(D) Một giáo sư</p>', 1003, '42252db43b18e24e', 1000, 21, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1093, 94, NULL, NULL, 'Why does the speaker say, “this program is only made possible by the financial support of our members\"?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Tại sao người nói nói, \"chương trình này chỉ được thực hiện nhờ sự hỗ trợ tài chính của các thành viên của chúng tôi?”</p><p>(A) Để khuyến khích người nghe đóng góp</p><p>(B) Xin lỗi vì một số tập có hạn</p><p>(C) Để ngăn mọi người nhận được tiền thưởng</p><p>(D) Bày tỏ lo lắng về một đề xuất</p>', 1003, '42252db43b18e24e', 1000, 21, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1094, 95, NULL, NULL, 'Look at the graphic. On which date is the talk being given?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Nhìn vào đồ họa. Buổi nói chuyện được diễn ra vào ngày nào?</p><p>(A) 3 tháng 6</p><p>(B) 10 tháng 6</p><p>(C) 17 tháng 6</p><p>(D) 2 tháng 6</p>', 1003, '42252db43b18e24e', 1000, 22, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1095, 96, NULL, NULL, 'What will the listeners do after the break?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nghe sẽ làm gì sau giờ giải lao?</p><p>(A) Trả lời các câu hỏi khảo sát</p><p>(B) Tham gia làm việc nhóm</p><p>(C) Xem xét một số hồ sơ xin việc</p><p>(D) Xem video</p>', 1003, '42252db43b18e24e', 1000, 22, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1096, 97, NULL, NULL, 'What does the speaker remind the listeners about?', NULL, '<p><strong>Dịch đáp án:</strong></p><p>Người nói nhắc nhở người nghe về điều gì?</p><p>(A) Một số câu hỏi nghiên cứu</p><p>(B) Một số thay đổi về lịch trình</p><p>&nbsp;(C) Phương thức thanh toán</p><p>(D) Tờ điểm danh</p>', 1003, '42252db43b18e24e', 1000, 22, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1097, 98, NULL, NULL, 'Who is the speaker?', NULL, '<p>Ai là người nói?</p><p>(A) Một nhân viên bảo vệ</p><p>(B) Một điều phối viên dự án</p><p>(C) Một người hướng dẫn khóa học</p><p>(D) Một nhà báo tin tức</p>', 1003, '42252db43b18e24e', 1000, 23, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1098, 99, NULL, NULL, 'Look at the graphic. Where will herbs be planted?', NULL, '<p>Nhìn vào hình ảnh. Các loại thảo mộc sẽ được trồng ở đâu?</p><p>(A) Ô 1</p><p>(B) Ô 2</p><p>(C) Ô 3</p><p>(D) Ô 4</p>', 1003, '42252db43b18e24e', 1000, 23, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1099, 100, NULL, NULL, 'What does the speaker plan to do on Saturday?', NULL, '<p>Người nói dự định làm gì vào Thứ Bảy?</p><p>(A) Dẫn dắt một chuyến tham quan</p><p>(B) Tham dự một buổi dã ngoại</p><p>(C) Chụp một số bức ảnh</p><p>(D) Lắp đặt hàng rào</p>', 1003, '42252db43b18e24e', 1000, 23, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1100, 101, NULL, NULL, 'Departmental restructuring will be discussed at the _____ monthly meeting', NULL, '<p>Cần một điền tính từ thích hợp.</p><p>A. Next A. kế tiếp</p><p>B. Always (adv) luôn luôn</p><p>C. Soon (adv) sớm</p><p>D. Like A. giống</p><p>Tạm dịch/Mở rộng: Vấn đề tái cấu trúc bộ phận sẽ được thảo luận tại cuộc họp hàng tháng tiếp theo.</p>', 1004, '99bed9945a6ed5e2', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
(1101, 102, NULL, NULL, 'To keep _____ park beautiful, please place your non recyclables in the available trash cans.', NULL, '<p>Cần điền một tính từ trước danh từ “park”.</p><p>Tạm dịch/Mở rộng: Để giữ cho công viên của chúng ta thật đẹp, vui lòng để rác thải không thể tái chế vào thùng rác ở đó.</p><p>Keep sth adj: giữ sth (tính từ)</p>', 1004, '99bed9945a6ed5e2', 1000, NULL, '2024-08-07 06:11:05', '2024-08-07 06:11:05', NULL),
