INSERT INTO `question_types` (`type_id`, `type_name`, `type_slug`, `type_thumb`, `type_desc`, `part_id`, `created_at`, `updated_at`) VALUES
(1000, 'Mô tả tranh', 'mo-ta-tranh', '{\"asset_id\":\"d76f8afcf4991a0bde5e945a2d838f74\",\"public_id\":\"toeic/documents/images/part-1\",\"format\":\"png\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005125/toeic/documents/images/part-1.png\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005125/toeic/documents/images/part-1.png\"}', 'Thí sinh sẽ nghe 1 lần duy nhất 4 câu mô tả về một bức tranh. Sau đó chọn 1 đáp án mô tả đúng nhất bức tranh đó.', '1b338528c6012352', '2024-08-07 06:11:05', '2024-08-07 06:13:12'),
(1001, 'Hỏi và đáp', 'hoi-va-dap', '{\"asset_id\":\"834fd761d1f4dd007e410bf0f9c7e079\",\"public_id\":\"toeic/documents/images/part-2\",\"format\":\"png\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005320/toeic/documents/images/part-2.png\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005320/toeic/documents/images/part-2.png\"}', 'Thí sinh sẽ nghe 1 lần duy nhất 3 câu hỏi đáp cho 1 câu hỏi hoặc 1 câu nói. Sau đó chọn câu hỏi đáp phù hợp nhất.', '3ce12c00bb4cf089', '2024-08-07 06:11:05', '2024-08-07 06:16:22'),
(1002, 'Đoạn hội thoại', 'doan-hoi-thoai', '{\"asset_id\":\"eebe68ffe40bc9a93f1fdaef36b696c2\",\"public_id\":\"toeic/documents/images/part-3\",\"format\":\"png\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005348/toeic/documents/images/part-3.png\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005348/toeic/documents/images/part-3.png\"}', 'Thí sinh sẽ nghe 1 lần duy nhất các đoạn hội thoại giữa 2 hoặc 3 người. Mỗi đoạn hội thoại sẽ có 4 câu hỏi, mỗi câu hỏi có 4 lựa chọn. Thí sinh đọc câu hỏi sau đó chọn câu trả lời phù hợp nhất.', '45ec88f1298a1d01', '2024-08-07 06:11:05', '2024-08-07 06:16:39'),
(1003, 'Bài nói ngắn', 'bai-noi-ngan', '{\"asset_id\":\"291958be62ea4e6feec5a9dd296420f1\",\"public_id\":\"toeic/documents/images/part-4\",\"format\":\"png\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005365/toeic/documents/images/part-4.png\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005365/toeic/documents/images/part-4.png\"}', 'Thí sinh sẽ nghe 1 lần duy nhất các bài nói ngắn. Mỗi bài sẽ có 3 câu hỏi, mỗi câu hỏi có 4 lựa chọn. Thí sinh đọc câu hỏi sau đó chọn câu trả lời phù hợp nhất.', '42252db43b18e24e', '2024-08-07 06:11:05', '2024-08-07 06:16:47'),
(1004, 'Hoàn thành câu', 'hoan-thanh-cau', '{\"asset_id\":\"99a371b0a73337abe4c8831421d07826\",\"public_id\":\"toeic/documents/images/part-5\",\"format\":\"png\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005386/toeic/documents/images/part-5.png\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005386/toeic/documents/images/part-5.png\"}', 'Chọn đáp án đúng nhất trong 4 đáp án để hoàn thành câu.', '99bed9945a6ed5e2', '2024-08-07 06:11:05', '2024-08-07 06:16:58'),
(1005, 'Hoàn thành đoạn văn', 'hoan-thanh-doan-van', '{\"asset_id\":\"cd75f985d7d15ccc8b52bc3d900c4c7f\",\"public_id\":\"toeic/documents/images/part-6\",\"format\":\"png\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005406/toeic/documents/images/part-6.png\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005406/toeic/documents/images/part-6.png\"}', 'Chọn đáp án đúng nhất trong 4 đáp án để hoàn thành câu.', 'd60c451950af3846', '2024-08-07 06:11:05', '2024-08-07 06:17:32'),
(1006, 'Đoạn đơn', 'doan-don', '{\"asset_id\":\"b4d2c83730521469a357c769b1d59844\",\"public_id\":\"toeic/documents/images/part-7\",\"format\":\"jpg\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005459/toeic/documents/images/part-7.jpg\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005459/toeic/documents/images/part-7.jpg\"}', 'Thí sinh sẽ đọc các bài đọc hiểu sau đó chọn đáp án đúng nhất cho các câu hỏi. Mỗi bài đọc sẽ bao gồm 2 - 4 câu hỏi.', 'eeff3ec8219669de', '2024-08-07 06:11:05', '2024-08-07 06:17:48'),
(1007, 'Đoạn kép', 'doan-kep', '{\"asset_id\":\"be9e654abe9a0ef95cf6ad390f17c4bb\",\"public_id\":\"toeic/documents/images/part-7-2\",\"format\":\"jpg\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005475/toeic/documents/images/part-7-2.jpg\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005475/toeic/documents/images/part-7-2.jpg\"}', 'Thí sinh sẽ đọc các bài đọc hiểu sau đó chọn đáp án đúng nhất cho các câu hỏi. Mỗi bài đọc sẽ bao gồm 5 câu hỏi.', 'eeff3ec8219669de', '2024-08-07 06:11:05', '2024-08-07 06:17:57'),
(1008, 'Đoạn ba', 'doan-ba', '{\"asset_id\":\"f6f77645d4a4c2db1fc21cca0f4da063\",\"public_id\":\"toeic/documents/images/part-7-3\",\"format\":\"jpg\",\"resource_type\":\"image\",\"url\":\"http://res.cloudinary.com/dtsq971i7/image/upload/v1723005489/toeic/documents/images/part-7-3.jpg\",\"secure_url\":\"https://res.cloudinary.com/dtsq971i7/image/upload/v1723005489/toeic/documents/images/part-7-3.jpg\"}', 'Thí sinh sẽ đọc các bài đọc hiểu sau đó chọn đáp án đúng nhất cho các câu hỏi. Mỗi bài đọc sẽ bao gồm 5 câu hỏi.', 'eeff3ec8219669de', '2024-08-07 06:11:05', '2024-08-07 06:18:08');
